insert into public.oops_workspace(id,state) values(1,'{"schema":3,"datasetId":"oops-integrated-124","savedAt":"2026-10-26T04:03:21.785093+00:00","cases":{"OOPS-001":{"elements":["[제공 HTML의 보도 인용]\nV040-U01 · 김옥빈: “계산할 때 할인카드를 내밀면 분위기가 깨져서 실망스럽다”","2010년 보도는 사랑 고백이나 생일의 특별한 이벤트 뒤 계산 상황을 전제로 인용했다. 2015년 보도는 일반적인 데이트 계산으로 더 짧게 인용하므로, 특별한 날의 취향을 모든 할인카드 이용자에 대한 평가로 동일시하지 않았다.","데이트 상대의 할인카드 사용. 모든 카드 이용자를 직접 지칭한 것으로 확장하지 않음.","생일·사랑 고백 같은 특별한 이벤트를 전제로 했다는 앞 문장이 중요하다. 모든 할인카드 사용을 비난한 말인지 특정 상황의 취향인지 달라지므로 카드 혜택·소비자 통계보다 원 대화 복원이 우선이다. 대본을 읽었다는 설명은 당사자의 후속 진술이다.","[비판 해석 요약] 절약을 부정적으로 평가하거나 데이트 상대에게 소비 부담을 요구한다는 비판. 특별한 상황의 개인 취향이라는 반론·맥락 차이가 있음. [원자료의 설명·반론] 2015년 세계일보는 스태프가 써준 말을 읽었고 거부할 수 있었는데 그러지 못했다는 본인의 해명을 전함. 대본·제작진 반론은 독립 확인하지 못함.","[분석자 도출] 특정한 날의 소비 취향을 상대의 인격·가치 평가로 확장하는지 확인한다. 앞 조건을 생략해 일반적 절약 비하로 바꾸지 않는다.","[제공 HTML의 문제 제기 기록] 온라인 이용자의 비판을 2010·2015년 보도가 회고. 당시 전체 게시물·여론 규모는 미확인; 후속 방송의 여성 평가 순위를 연구자의 평가로 채택하지 않음. 핵심 지적: 절약을 부정적으로 평가하거나 데이트 상대에게 소비 부담을 요구한다는 비판. 특별한 상황의 개인 취향이라는 반론·맥락 차이가 있음."],"status":"제공자료 정리","deletedAt":null,"history":[]},"OOPS-002":{"elements":["[제공 HTML의 보도 인용]\nV007-U01 · 대학생 출연자: “키가 작은 남자는 루저라고 생각한다”","이성의 키와 선호에 대한 대화에서 특정 신장 이하 남성을 부르는 표현이 쟁점. 대본에 따른 발언이라는 출연자 주장과 제작 책임이 함께 제기됐다.","키가 작은 남성 일반. 개인의 이성 선호에서 신체 조건에 따른 가치 평가로 대상이 확장됨.","‘루저’의 패배자라는 뜻 외에 특정 사건 지식은 핵심 비판을 이해하는 데 필요하지 않다. 키의 선호를 사람의 가치 평가로 바꾸는 대화가 핵심이며, 대본 작성·사전 협의는 제작진에게 확인할 정보다.","[비판 해석 요약] 개인적 선호를 넘어 신체 조건으로 사람의 가치를 낮춘다는 비판. [원자료의 설명·반론] 제작진은 새 세대의 생각을 소개하려 했다고 설명하고 사과. 대본 강제 여부는 독립 확인하지 못함.","[분석자 도출] 외모·신체 조건에 대한 선호와 그 조건을 가진 사람의 가치·존엄을 낮추는 표현을 구분한다.","[제공 HTML의 문제 제기 기록] 시청자·작은 키 관련 모임·언론중재 신청. iMBC는 11월 18일 기준 관련 신청 78건을 보도했으나 이것은 중복 없는 비판자 수가 아님. 핵심 지적: 개인적 선호를 넘어 신체 조건으로 사람의 가치를 낮춘다는 비판."],"status":"제공자료 정리","deletedAt":null,"history":[]},"OOPS-003":{"elements":["[제공 HTML의 보도 인용]\nV008-U01 · 장희민: “군대는 죽이는 거 배워 오는 곳”","남녀의 언어 차이 등을 설명하는 강의에서 군 복무와 출산을 대비했다. 수능 강의의 학습 내용과 강사의 가치 평가를 구별해야 하는 장면.","군 복무자 일반 및 출산과 대조되는 남성 집단. 특정 군인의 실제 행위를 지칭한 것은 아님.","남녀의 언어 차이를 다루던 수업 주제와 군 복무·출산을 대조한 앞뒤 문장이 필요하다. 특정 군 사건을 추가로 연결할 근거는 없으며, 군 복무 전체를 일반화했다는 비판과 강사의 설명을 함께 기록한다.","[비판 해석 요약] 군 복무자를 일괄적으로 생명을 해치는 집단처럼 서술했다는 비판. [원자료의 설명·반론] 강사는 강의 긴장 등을 언급하며 사과한 것으로 보도. 사장은 강의가 충분히 검증되지 않고 게시됐다고 인정.","[분석자 도출] 군의 기능 설명과 군 복무자 전체를 폭력적·열등한 집단으로 규정하는 일반화를 구분한다.","[제공 HTML의 문제 제기 기록] 인터넷 이용자들의 항의와 EBS 사장 사과가 확인됨. 항의 규모의 모집단은 확인 불가. 핵심 지적: 군 복무자를 일괄적으로 생명을 해치는 집단처럼 서술했다는 비판."],"status":"제공자료 정리","deletedAt":null,"history":[]},"OOPS-004":{"elements":["[제공 HTML의 보도 인용]\nV009-U01 · 채한석: “못생겼는데 까불고 있어. 졸부 딸이면 다야?”","다른 출연자 맥신쿠와의 스타일링·관계 갈등에서 상대의 외모와 부를 공격하는 말. 기사에 따르면 일부 욕설은 효과음·입 가림 편집으로 처리됐다.","함께 출연한 맥신쿠의 외모·가정 배경. 실제 자산이나 성격은 확인하지 않음.","별도 사건 지식 없이 외모·가정 배경을 직접 공격하는 표현에서 비판 이유를 확인할 수 있다. 두 사람의 실제 사적 갈등이나 자산을 추정할 필요는 없고, 연출·대본 여부는 미확인이다.","[비판 해석 요약] 갈등을 다루는 과정에서 상대를 외모·출신 배경으로 모욕하고 욕설을 오락화했다는 비판. [원자료의 설명·반론] 제작진·출연자의 직접 반박 미확보. 연출된 갈등인지도 확인되지 않음.","[분석자 도출] 갈등의 쟁점과 관계없이 상대의 외모·가정 배경을 모욕의 근거로 사용하는지 살핀다.","[제공 HTML의 문제 제기 기록] 기사에 인용된 온라인 이용자 의견. 반응 수 미확인; 기사의 과장된 제목을 규모 근거로 쓰지 않음. 핵심 지적: 갈등을 다루는 과정에서 상대를 외모·출신 배경으로 모욕하고 욕설을 오락화했다는 비판."],"status":"제공자료 정리","deletedAt":null,"history":[]},"OOPS-005":{"elements":["[제공 HTML의 보도 인용]\nV010-U01 · 김진표: “코브라가 ‘운지’를 하고 맙니다”","헬리콥터가 추락하는 장면을 설명하며 인터넷에서 본 표현을 사용했다는 본인 해명. 특정인의 죽음을 조롱하는 온라인 용례가 쟁점이었다.","직접 대상은 추락하는 헬리콥터. 문제 표현이 연상시키는 별도 대상은 고 노무현 전 대통령.","‘운지’가 단순한 추락 묘사 외에 노무현 전 대통령의 죽음을 조롱하는 온라인 용례로 사용됐다는 배경이 핵심이다. 당시 보도가 이 용례를 구체적으로 설명하며, 김진표는 그 의미를 몰랐다고 밝혔다. 특정 커뮤니티 가입이나 정치 성향은 이 말만으로 추정하지 않는다.","[비판 해석 요약] 단순한 추락 묘사로 쓰였다는 해명과 달리, 해당 표현이 정치인 사망 비하로 유통된다는 지적. [원자료의 설명·반론] 인터넷 댓글에서 보고 단순히 떨어진다는 뜻으로 알았으며 정치적 의미를 몰랐다고 설명.","[분석자 도출] 일상적 묘사처럼 쓰인 표현에 고인 조롱의 통용 의미가 있는지 확인하고, 그 사용만으로 소속·정치 성향·고의를 단정하지 않는다.","[제공 HTML의 문제 제기 기록] 온라인 이용자·보도. 특정 커뮤니티 소속이나 정치 성향은 이 발언으로 확정할 수 없음. 핵심 지적: 단순한 추락 묘사로 쓰였다는 해명과 달리, 해당 표현이 정치인 사망 비하로 유통된다는 지적."],"status":"제공자료 정리","deletedAt":null,"history":[]},"OOPS-006":{"elements":["[제공 HTML의 보도 인용]\nV012-U01 · 곽정은: “이 남자 침대에서 어떨까?”\nV012-U02 · 곽정은: “키스 실력이 궁금하다”","장기하의 무대에서 보이는 에너지와 로이킴의 모습에 대한 호감을 성적 상상으로 표현했다. 출연자의 웃음이나 녹화 참여를 성적 평가의 공개 동의로 간주하지 않는다.","U01은 장기하의 성적 매력, U02는 로이킴의 키스 능력. 서로 다른 대상을 합치지 않음.","성적 평가의 대상이 실존 출연자라는 정보와 대화의 호감 표현 맥락이 필요하다. 특별한 외부 사건 지식은 없어도 비판 이유를 이해할 수 있으며, 잡지와 TV 독자층 차이는 당사자가 나중에 설명한 배경이다.","[비판 해석 요약] 호감 표현이라도 상대의 성적 능력을 공개 평가하는 방식은 부적절하다는 비판. [원자료의 설명·반론] 2014년에는 칭찬의 취지였다고 설명. 2026년에는 잡지 독자층에서 통하던 표현을 더 넓은 TV 시청자에게 사용한 판단을 되돌아보며 사과했다고 보도됨.","[분석자 도출] 호감·칭찬의 취지라도 실존인의 성적 능력·사생활을 공개 상상·평가하는지 확인한다. 웃음이나 출연을 포괄적 동의로 취급하지 않는다.","[제공 HTML의 문제 제기 기록] 온라인 이용자와 보도; 장기하·로이킴이 직접 동일한 문제를 제기했는지는 미확인. 핵심 지적: 호감 표현이라도 상대의 성적 능력을 공개 평가하는 방식은 부적절하다는 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-007":{"elements":["[제공 HTML의 보도 인용]\nV058-U01 · 엄성섭: “이게 기자에요? 완전 쓰레기지 거의”","이완구 국무총리 후보자의 발언 녹취를 다른 매체·정당이 입수한 경위를 비판하던 중 한국일보 기자를 지칭했다.","이완구 후보자 녹취 관련 취재·전달 경위에 관여한 한국일보 기자.","누구의 어떤 취재·녹취 전달을 비판하는지 이해하려면 인사청문회 보도 배경이 필요하다. 그러나 상대를 ‘쓰레기’로 지칭했다는 표현상 쟁점을 파악하는 데 녹취 전달의 잘잘못을 먼저 확정할 필요는 없다.","[비판 해석 요약] 공정성을 지켜야 하는 방송에서 비속어로 타사 기자를 공격했다며 한국일보지회가 사과와 문책을 요구했다. 녹취 전달의 적절성에 대한 논쟁과 사람을 모욕하는 표현을 분리했다. [원자료의 설명·반론] 엄성섭은 다음 날 방송에서 부적절한 표현이었다며 해당 기자와 시청자에게 사과했다.","[분석자 도출] 취재·정보 전달 행위에 대한 비판과 기자 개인을 비속어·물건에 빗대 모욕하는 표현을 구분한다.","[제공 HTML의 문제 제기 기록] 한국기자협회 한국일보지회의 2월 12일 항의 공문 내용을 보도로 확인. 핵심 지적: 공정성을 지켜야 하는 방송에서 비속어로 타사 기자를 공격했다며 한국일보지회가 사과와 문책을 요구했다. 녹취 전달의 적절성에 대한 논쟁과 사람을 모욕하는 표현을 분리했다."],"status":"제공자료 정리","deletedAt":null,"history":[]},"OOPS-008":{"elements":["[제공 HTML의 보도 인용]\nV042-U01 · 김윤태: “너 그냥 장애인 X끼야 너”\nV042-U02 · 김윤태: “니네 아빠는 장애인 아빠라는 타이틀을 갖고 있다”","자신의 개인정보를 유출했다고 주장하는 상대를 방송에 불러 대면한 상황. 개인정보 유출 주장 자체와 상대의 건강 상태를 연구자가 독립 확인한 것은 아님.","개인정보를 유출했다고 주장하는 상대와 그 아버지. 상대의 실제 장애·행위는 독립 확인되지 않음.","갈등 상대에 대한 장애 언급을 모욕에 사용했다는 점은 영상 속 발언에서 드러난다. 개인정보 유출 여부는 갈등 배경에 관한 발언자의 주장으로만 확인됐으며, 장애 비하 문제를 이해하기 위해 이를 사실로 인정할 필요는 없다.","[비판 해석 요약] 갈등 상대를 공격하면서 장애를 모욕의 근거로 삼고 가족에게까지 확장했다는 비판. [원자료의 설명·반론] 자신의 개인정보가 유출됐고 당시 분노 때문에 그런 말을 했다는 취지의 해명 영상이 보도됨. 상대의 행위가 사실이라고 확정하지 않음.","[분석자 도출] 갈등 상대를 공격하면서 장애를 모욕의 근거로 쓰거나 가족에게 비하를 확장하는지 확인한다.","[제공 HTML의 문제 제기 기록] 구독자 공개 지적; 한국지체장애인협회 민원 게시판에 2월 14일 17시까지 처벌 요구 글 18건이 올라왔다고 한겨레 보도. 18명 또는 전체 여론 규모로 환산하지 않음. 핵심 지적: 갈등 상대를 공격하면서 장애를 모욕의 근거로 삼고 가족에게까지 확장했다는 비판."],"status":"제공자료 정리","deletedAt":null,"history":[]},"OOPS-009":{"elements":["[제공 HTML의 보도 인용]\nV019-U01 · 주예지: “그렇게 공부할 거면 용접 배워서 호주 가야 한다”","수학 가형·나형 등급의 비교를 논의하다 낮은 성적을 받는 학생의 진로를 용접에 빗댔다. 용접을 흉내 내는 소리·동작은 별도 비언어 요소.","낮은 수학 성적을 받는 학생과 용접 직종·종사자.","수학 가형·나형 성적 비교라는 교육 맥락은 발언의 계기를 설명한다. 핵심 비판은 낮은 성적과 용접 직업을 연결한 말 자체에 있으므로 용접공의 실제 임금·취업 전망을 반드시 알아야만 이해되는 사례는 아니다.","[비판 해석 요약] 특정 기술 직업을 공부를 못하는 사람이 가는 곳으로 낮춘다는 비판. [원자료의 설명·반론] 부적절한 예시였다는 취지로 사과. 협회는 이후 사과의 태도 등에 추가 문제를 제기한 것으로 보도.","[분석자 도출] 학업 성취도를 특정 직업·종사자의 낮은 가치에 연결하는지 살핀다. 직업 권유 자체와 비하 문맥을 구분한다.","[제공 HTML의 문제 제기 기록] 대한용접협회의 공개 사과 요구와 이용자 반응이 보도됨. 핵심 지적: 특정 기술 직업을 공부를 못하는 사람이 가는 곳으로 낮춘다는 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-010":{"elements":["[확정 범위·보도 인용] 김민아: “에너지는 어디에 푸냐”, “혼자 집에 있을 때 뭐하냐.”","코로나19 온라인 수업을 듣는 남자 중학생에게 화상 인터뷰로 연속 질문.","인터뷰에 참여한 남자 중학생.","핵심 이해에 별도의 사건 배경·은어 지식은 필요하지 않음. 연령과 질문 순서가 문맥에 포함됨.","[확정한 해석] 미성년자의 성적 사생활을 우회적으로 묻고 희화화한다.","[분석자 도출] 미성년자의 성적 사생활을 보호하고 희화화하지 않는다.","[보도] 시청자들이 미성년자를 향한 성적 암시 질문이 부적절하다고 비판."],"status":"기존 확정","deletedAt":null,"history":[]},"OOPS-011":{"elements":["[제공 HTML의 보도 인용]\nV050-U01 · 박나래: “너무 뒤가 T다”\nV050-U02 · 박나래: “너무 Y이다”","남성 인형의 옷을 갈아입히고 신체를 늘리는 체험 중 신체 형태를 성적으로 묘사했다. 인형 팔을 사타구니 쪽으로 옮기는 행동·성적 암시 자막이 함께 문제 됐다. 앞 회차의 다른 발언은 이번 두 인용에 합치지 않았다.","장난감 남성 인형의 신체 형태. 특정 실존인의 성적 사생활을 직접 묻는 장면과는 구분.","헤이지니가 어린이 대상 콘텐츠로 알려져 있다는 배경이 아동 접근 우려와 연결된다. 다만 이 프로그램 자체가 어린이 전용이라고 확정하지 않으며, 실제 연령 제한·시청층은 별도 확인이 필요하다.","[비판 해석 요약] 성적 언행을 장난감 체험에 결합한 점, 키즈 크리에이터 헤이지니와의 콘텐츠에서 아동 시청 가능성을 고려하지 않았다는 비판이 보도됐다. 발언만으로 전체 논란을 설명하기 어려운 결합 사례다. [원자료의 설명·반론] 박나래 측은 캐릭터와 소품을 전달받았을 때 표현을 걸렀어야 했다고 밝혔다. 제작진도 과한 연출과 설정에 대한 책임을 인정했다.","[분석자 도출] 발언·동작·자막의 결합이 성적 의미를 만드는지 살피고, 장난감 체험과 시청층의 기대·접근 가능성을 함께 확인한다.","[제공 HTML의 문제 제기 기록] 기사에 인용된 일부 시청자·온라인 이용자. 실제 아동 시청 비율은 확인되지 않았다. 핵심 지적: 성적 언행을 장난감 체험에 결합한 점, 키즈 크리에이터 헤이지니와의 콘텐츠에서 아동 시청 가능성을 고려하지 않았다는 비판이 보도됐다. 발언만으로 전체 논란을 설명하기 어려운 결합 사례다."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-012":{"elements":["[제공 HTML의 보도 인용]\nV045-U01 · 태민: “흰 자랑 치아밖에 안 보인다”\nV045-U02 · 키: “왜 이렇게 탔냐”","골프를 즐기는 민호의 햇볕에 탄 피부를 멤버들이 이야기하던 장면. 친한 동료 사이의 대화라는 제작 맥락과 피부색에 대한 문화권별 수용이 교차함.","햇볕에 탄 민호의 피부색. 특정 인종을 직접 지칭했다고 확정하지 않음.","민호가 골프로 햇볕에 탄 피부를 동료가 언급한 맥락과 해외 팬이 피부색을 비하로 읽었다는 반응이 필요하다. 문화권별 피부색 차별의 맥락은 해석을 돕지만 특정 인종을 지목했다거나 차별 의도가 있었다고 확정하는 근거는 아니다.","[비판 해석 요약] 일부 해외 팬이 피부색 언급을 인종차별적 표현으로 비판. 친분이나 현장 반응만으로 공개 수용자의 동의를 추정하지 않음. [원자료의 설명·반론] 키·태민이 사과했고, 제작 측은 실제 대화 모습을 담는 과정에서 부적절한 말이 포함됐다고 설명.","[분석자 도출] 동료의 피부색을 웃음 소재로 낮춰 평가하는지, 문화권별 차별 맥락에서 어떻게 수용되는지 살핀다. 친분만으로 공개 수용자의 동의를 가정하지 않는다.","[제공 HTML의 문제 제기 기록] 일부 해외 팬의 비판이 보도됨. 나라별 비중·전체 팬덤 의견 규모는 미확인. 핵심 지적: 일부 해외 팬이 피부색 언급을 인종차별적 표현으로 비판. 친분이나 현장 반응만으로 공개 수용자의 동의를 추정하지 않음."],"status":"제공자료 정리","deletedAt":null,"history":[]},"OOPS-013":{"elements":["[제공 HTML의 보도 인용]\nV028-U01 · 정재형: “내가 공무원이면, 여기 발령받으면, 여기까지만 할게”\nV028-U02 · 화자 미확인 — 세 출연자 중 1인: “할매 맛이다. 내가 할머니의 살을 뜯는 것 같다”","지역 여행 중 근무지·음식·하천을 평가한 연속 장면. 특정 식당 상호 노출과 현장 태도는 발언과 결합했지만 별도 요소로 표시했다.","U01은 영양군 근무 환경·지역 이미지, U02는 지역 음식과 노년 여성의 신체 이미지. 두 표현의 화자 확인 상태를 구분.","식별 가능한 실제 지역·상점이라는 점과 현장의 상대가 직접 영업하는 주민이라는 정보가 중요하다. 지역 통계나 역사 지식이 없어도 연속된 폄하 표현의 문제 제기를 이해할 수 있으며, 식당의 객관적 맛이나 출연자의 고의는 여기서 판정하지 않는다.","[비판 해석 요약] 지역과 주민을 일관되게 낮춰 웃음거리로 삼고 노인의 몸을 음식 비유로 소비했다는 비판. 부정적 맛 평가 일반을 금지해야 한다는 결론은 아님. [원자료의 설명·반론] 출연진은 지역에 미칠 부정적 영향을 충분히 숙고하지 못했다고 사과하고 상인 방문 사과 경위를 설명.","[분석자 도출] 부정적 여행·맛 평가와 지역·주민 전체를 낮추는 표현을 구분하고, 사람의 신체를 조롱성 음식 비유에 사용하는지 본다.","[제공 HTML의 문제 제기 기록] 시청자 댓글·언론 보도. 영상 조회수는 항의 인원 수가 아니며 상인들의 의사는 제작진 설명과 독립 인터뷰를 구별해야 함. 핵심 지적: 지역과 주민을 일관되게 낮춰 웃음거리로 삼고 노인의 몸을 음식 비유로 소비했다는 비판. 부정적 맛 평가 일반을 금지해야 한다는 결론은 아님."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-014":{"elements":["[제공 HTML의 보도 인용]\nV029-U01 · 오구라 유나: “몸매가 좋으니까. 꼭 데뷔해달라”","AV 업계 종사 게스트가 동석한 지원에게 하는 권유. 지원이 한국에서 이미 연기를 시작했다고 답하는 맥락이 보도됐으며, 성인물 출연을 수락한 것으로 해석해서는 안 된다.","오구라 유나가 권유한 대상은 걸그룹 시그니처의 지원.","AV가 성인 영상 업계라는 뜻과 권유 상대가 걸그룹 멤버라는 정보가 성적 직업 권유의 의미와 연결된다. 상대의 경력 의향이나 공개 동의는 농담에 웃었다는 사실만으로 확인할 수 없다.","[비판 해석 요약] 상대의 몸매를 평가하며 성인물 출연을 권유하는 발언을 오락으로 내보냈다는 비판. [원자료의 설명·반론] 제작진은 지원을 배려하지 못했다고 사과하고 탁재훈이 만류한 장면을 재미를 위해 편집했다고 설명.","[분석자 도출] 상대의 신체를 평가하며 성인영상 출연을 권유하는지 살핀다. 일반 배우 활동 답변이나 웃음을 성인물 출연 동의로 해석하지 않는다.","[제공 HTML의 문제 제기 기록] 영상 시청자·온라인 이용자·언론. 지원의 독립적인 문제 제기와 공개 동의 범위는 미확인. 핵심 지적: 상대의 몸매를 평가하며 성인물 출연을 권유하는 발언을 오락으로 내보냈다는 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-015":{"elements":["[제공 HTML의 보도 인용]\nV030-U01 · 이기호: “나는 여자라면을 먹고 싶다. 가장 맛있는 라면 아니냐”","관중의 응원 문구 여자라면 최재훈이 화면에 잡힌 뒤 조건형 표현을 음식 라면으로 돌린 말장난. 응원 문구는 음성 발언이 아니라 발언을 유발한 화면 요소다.","관중의 응원 문구 속 ‘여자’와 이를 계기로 일반화된 여성. 관중의 실제 성적 의사·감정은 미확인.","중계 화면의 응원 문구와 라면을 계기로 여성을 지칭한 말장난이라는 현장 맥락이 필요하다. 별도 사건·역사 지식은 핵심 비판에 필요하지 않으며 관중의 성적 동의나 감정은 추정하지 않는다.","[비판 해석 요약] 여성을 먹는 대상으로 비유하는 성적 발언이라는 비판. [원자료의 설명·반론] 당일 중계 중 부적절한 언어였다고 수습한 것으로 보도. 다음 날 방송사가 재차 사과.","[분석자 도출] 말장난에서 여성을 음식처럼 ‘먹는 대상’으로 바꾸는 성적 의미가 형성되는지 화면 문구와 발언을 함께 확인한다.","[제공 HTML의 문제 제기 기록] 시청자·온라인 반응과 방송사 자체 사과. 반응의 전체 규모 미확인. 핵심 지적: 여성을 먹는 대상으로 비유하는 성적 발언이라는 비판."],"status":"제공자료 정리","deletedAt":null,"history":[]},"OOPS-016":{"elements":["[제공 HTML의 보도 인용]\nV032-U01 · 김원훈: “여기 모텔촌 아니냐”\nV032-U02 · 김원훈: “어제 집에 다 들어가셨죠?”","선릉 쪽으로 가는 일반인 커플에게 이동 장소와 귀가·숙박을 연결해 물었다. 상대의 답변 뒤에도 관계를 암시하는 농담이 이어진 것으로 보도.","거리 인터뷰에 참여한 일반인 커플의 귀가·숙박 및 성적 사생활.","거리에서 만난 일반인 커플에게 귀가·숙박을 물은 흐름만으로 사생활 침범 비판을 이해할 수 있다. 실제 숙박 계획·성적 관계나 모텔 이용 여부는 확인할 필요가 없으며, 확인되지 않은 사생활을 농담의 사실 전제로 쓰지 않는다.","[비판 해석 요약] 일반인 커플의 성적 사생활을 거리 인터뷰의 웃음 소재로 삼았다는 비판. [원자료의 설명·반론] 제작진은 시청자가 불편할 수 있는 상황을 만들었다는 취지로 사과. 구체적인 내부 승인 이유는 미확인.","[분석자 도출] 상대의 답변과 무관하게 성적 사생활을 추정·반복 질문해 웃음 소재로 삼는지 살핀다. 실제 성적 관계는 추정하지 않는다.","[제공 HTML의 문제 제기 기록] 시청자·온라인 반응. 커플 본인의 사후 공개 의견·합의 내용은 미확보. 핵심 지적: 일반인 커플의 성적 사생활을 거리 인터뷰의 웃음 소재로 삼았다는 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-017":{"elements":["[제공 HTML의 보도 인용]\nV055-U01 · 김진웅: “누군가의 서브로는 못 산다”","결혼정보업체 상담 중 희망하는 결혼생활을 이야기하며 도경완을 예로 들었다. 엄지인이 왜 서브냐고 지적했으나 쉽지 않다고 거듭 말한 것으로 보도됐다.","결혼관의 비교 사례로 언급된 도경완과 장윤정의 부부 관계.","도경완과 장윤정이 부부라는 관계 정보가 지칭 대상을 이해하는 데 필요하다. 실제 수입·가사 분담을 추정할 필요는 없으며, 확인된 가족관계가 곧 서열의 근거는 아니다.","[비판 해석 요약] 부부의 역할을 서열로 평가하고 실제 동료를 보조적 존재로 낮췄다는 문제 제기. 장윤정과 도경완은 가족 사이에 서브는 없다는 취지로 반박했다. [원자료의 설명·반론] 김진웅은 의욕이 앞서 신중하지 못했다고 사과했다. 장윤정은 직접 사과 연락을 받았고 이를 받아들인다고 밝혔다.","[분석자 도출] 자신의 결혼관 설명을 실제 타인의 가족 내 역할·인격에 대한 서열화로 바꾸는지 확인한다.","[제공 HTML의 문제 제기 기록] 직접 언급된 당사자 부부의 SNS 반응과 KBS 청원 게시판 문제 제기를 보도로 확인. 핵심 지적: 부부의 역할을 서열로 평가하고 실제 동료를 보조적 존재로 낮췄다는 문제 제기. 장윤정과 도경완은 가족 사이에 서브는 없다는 취지로 반박했다."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-018":{"elements":["[제공 HTML의 보도 인용]\nV060-U01 · 고말숙: “남자친구 사귈 때 귀여워 보이는데 내가 되기만 하면 임신시키고 싶다”","지인 유튜버들과 연애·성적인 농담을 나누는 콘텐츠에서 나온 말로 보도됐다. 특정 실명 상대를 지칭했는지와 바로 앞 질문은 확인되지 않았다.","가정된 남자친구. 특정 실존 연인을 지칭하는지는 미확인.","특정 역사·사건 지식이 필요한 표현은 아니다. 해당 채널의 실제 대상 연령·연령 제한, 원영상과 숏폼의 맥락 차이는 별도 확인할 정보이며 본 조사에서는 확정하지 못했다.","[비판 해석 요약] 일부 이용자는 성적 농담의 수위와 반복, 성별에 따라 허용 기준이 달라지는 점을 비판했다. 다른 이용자는 원래 성인 취향의 콘텐츠에 대한 과도한 간섭이라고 반박했다. [원자료의 설명·반론] 고말숙은 숏폼 조회수와 채널 노출을 위해 수위를 높이려 했고 함께 나온 이들에게 미칠 영향을 생각하지 못했다고 설명하며 사과했다.","[분석자 도출] 성적 농담의 대상·반복·공개 범위를 확인한다. 성인 취향 콘텐츠라는 맥락과 숏폼에서 문맥이 달라지는 조건도 함께 살핀다.","[제공 HTML의 문제 제기 기록] 아시아타임즈가 SNS·커뮤니티 비판과 FM코리아 반론을 함께 인용. 전체 이용자의 찬반 비율은 알 수 없음. 핵심 지적: 일부 이용자는 성적 농담의 수위와 반복, 성별에 따라 허용 기준이 달라지는 점을 비판했다. 다른 이용자는 원래 성인 취향의 콘텐츠에 대한 과도한 간섭이라고 반박했다."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-019":{"elements":["[제공 HTML의 보도 인용]\nV035-U01 · 김남일: “야구는 스포츠라고 생각하지 않는다”","종목 간 경쟁을 웃음으로 다루는 토크에서 야구 출신 윤석민과 대화하며 야구의 스포츠 여부를 평가. 윤석민은 관중 수를 들어 반박한 것으로 원자료에 기록됨.","야구라는 종목의 스포츠로서 지위·가치. 대화 상대 윤석민이 배경에 있지만 그의 관중 동원 기여를 평가한 다른 발언은 제외.","김남일은 축구, 대화 상대 윤석민은 야구 선수 출신이며 프로그램은 종목 간 경쟁을 연출한 예능. 실제 체력 소모나 인기 수치의 우열을 판정할 필요는 없음. 후속 친분 설명은 당사자의 입장.","[비판 해석 요약] 야구 팬들은 타 종목의 스포츠로서 가치를 낮췄다고 비판. 김남일은 관중 수가 부러웠다는 취지를, 윤석민은 친분과 예능 맥락을 설명한 것으로 기록됨. 다른 출연자의 동조·관중 관련 평가는 제외.","[분석자 도출] 종목 간 농담·경쟁 연출을 넘어 다른 종목 자체의 가치·정당성을 일괄 부정하는지 살핀다. 실제 체력 소모·인기 순위를 비교해 우열을 판정하지 않는다.","[제공 HTML의 문제 제기 기록] 야구 팬·온라인 이용자의 비판이 보도됐다고 제공 HTML에 기록됨. 대화 상대의 개인적 수용과 팬들의 문제 제기는 구분. 핵심 지적: 야구의 스포츠로서 가치를 낮춰 말한다는 비판. 다른 출연자의 선수 기여 관련 발언은 이 기록의 검토 대상이 아님."],"status":"제공자료 정리","deletedAt":null,"history":[]},"OOPS-020":{"elements":["[제공 HTML의 보도 인용]\nV036-U01 · 김선태: “혹시 바이럴 마케팅 아니냐고 한 사람은 없었느냐”","리센느 원이의 과거 방언 사용 논란을 이야기하면서 과도한 비난이었다고 옹호한 뒤 나온 질문. 원이는 그룹에 영향이 갈까 두려웠다고 답한 것으로 보도됐다.","리센느 원이의 과거 방언 논란과 그 논란이 기획 홍보였는지에 대한 추정.","원이의 앞선 ‘무섭노’ 사용 논란(V048)과 그로 인한 당사자의 불안 설명이 질문의 의미를 바꾼다. ‘바이럴’이 단순 홍보 전략 질문인지 당사자의 고통을 의심하는 질문인지에는 그 앞 대화가 필요하며, 실제 기획 홍보였다는 증거는 확보하지 못했다.","[비판 해석 요약] 당사자가 힘들었다고 밝힌 과거 일을 다시 자극적인 웃음·홍보 소재로 소비한다는 비판. 썸네일·제목의 별도 문제와 음성 질문을 나눠 기록. [원자료의 설명·반론] 김선태는 첫 촬영에서 대본 소화에 급급해 문제를 인지하지 못했고 업로드 영상을 사전 검토하지 못했다고 설명.","[분석자 도출] 고통을 호소한 당사자에게 근거 없이 논란을 스스로 만든 것인지 의심하거나 홍보 소재로 전환하는지 앞 대화와 함께 살핀다.","[제공 HTML의 문제 제기 기록] 시청자·온라인 이용자 비판과 제작진·진행자 대응. 과거 방언이 실제로 특정 커뮤니티 소속을 뜻한다는 판단은 하지 않음. 핵심 지적: 당사자가 힘들었다고 밝힌 과거 일을 다시 자극적인 웃음·홍보 소재로 소비한다는 비판. 썸네일·제목의 별도 문제와 음성 질문을 나눠 기록."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-021":{"elements":["[확정 범위·보도 인용] 승우아빠: “아니, 당근에다 내면 중고들만 들어오겠지.”","식당 창업 조언 중 직원 구인 공고를 어디에 냈는지 묻고 ‘당근’이라는 답을 들은 상황.","당근을 통해 지원하는 구직자.","당근의 중고거래 이미지가 ‘중고’ 비유의 배경. 구인·구직 기능 자체가 비하의 근거는 아님.","[확정한 해석] 구직자를 중고품처럼 낮춰 부른다.","[분석자 도출] 구직 경로를 근거로 사람의 가치를 낮춰서는 안 된다.","[보도] 시청자들이 사람을 중고품에 빗댄 표현이 부적절하다고 비판."],"status":"기존 확정","deletedAt":null,"history":[]},"OOPS-022":{"elements":["[확정 범위·보도 인용] 미주: “어디까지 갔어?”, “너 남자 맞아?”","연애 질문 뒤 성관계를 추정하고, 상대가 부인했는데도 다시 묻고 남성성을 평가.","인터뷰에 참여한 남성 대학생.","촬영·질문·공개 동의의 범위는 미확인. 동의가 없었다고 확정하지 않음.","[확정한 해석] 성적 사생활을 웃음 소재로 삼고 경험 여부로 남성성을 평가한다.","[분석자 도출] 성적 사생활을 존중하고 성적 경험 여부로 남성성을 평가하지 않는다.","[보도] 시청자들이 성적 질문·상대의 부인 이후 이어진 농담·남성성 평가를 비판."],"status":"기존 확정","deletedAt":null,"history":[]},"OOPS-023":{"elements":["[보도 인용] 편집몬: “약간 그 후쿠시마 맛.”","일본 기타큐슈 여행 영상에서 편의점 생수를 마신 뒤 한 농담. 가요이의 말과 구분한다.","직접 지칭은 생수의 맛. 간접적으로 후쿠시마 지역·재난 피해를 연상시킴.","후쿠시마는 원전 사고와 지진 피해의 기억이 있는 지명이다. 물이 실제 오염됐다는 확인은 아님.","[비판 해석] 재난 피해와 방사능 우려를 가벼운 맛 표현으로 희화화했다. 당사자는 방류 이슈에 대한 풍자였다고 설명.","[분석자 도출] 재난·피해 지역을 웃음 소재로 삼을 때 피해 경험을 조롱하는 의미가 생기는지 살핀다.","[보도] 일본 구독자 등 일부 시청자가 여행지에서 재난을 빗댄 농담이 부적절하다고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-024":{"elements":["[보도 인용] 용찬우: “1920년대 일본이 … 한글을 보급한 것.” 중간 생략.","한글·한문과 식민지 시기 교육을 이야기한 2021년 영상이 2023년 재조명됨.","일본 식민 통치의 역할, 한글 보급과 한국인의 언어 사용.","한글 창제와 근대 보급은 구분해야 한다. 일제 시기 교육·조선어 정책의 시기별 자료가 주장 검증에 필요.","[보도된 쟁점 요약] 식민 통치가 한글 보급의 주역이라는 단정이 역사 인식을 왜곡한다는 해석.","[분석자 도출] 역사적 인과를 단정할 때 시기·정책·근거를 확인하고 창제와 보급을 혼동하지 않는다.","[보도] 국내 보도와 일본 매체가 주장을 논란으로 다룸. 구체적인 역사학계 검증은 이번 자료에서 미확인."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-025":{"elements":["[보도 인용] 슈카: “무난하게 임기를 마치고 그만두셨으면 좋겠다.”","2024년 12월 비상계엄 해제 이후 방송. 다음 대통령과 정치권에도 잘하기를 바란다는 말이 이어짐.","당시 대통령 및 이후 대통령들의 국정 운영·임기.","12·3 비상계엄 직후 탄핵·책임론이 제기된 시점이라는 사실이 해석에 영향을 줌.","[비판 해석] 계엄 책임 추궁·탄핵에 반대하는 말로 읽힘. 슈카는 누구든 이런 일 없이 임기를 마치길 바란 뜻이라 설명.","[분석자 도출] 정치 발언의 지시 대상과 앞뒤 조건을 확인하고, 특정 정책·사건 옹호와 일반적 희망을 구분한다.","[보도] 일부 누리꾼은 계엄 옹호·탄핵 반대로 비판. 문맥상 비꼼·일반론이라는 반론도 보도됨."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-026":{"elements":["[2차자료 요약] ① 심장수술 예정 시청자의 부탁에 대한 반응 ② 게임 중 지뢰 관련 농담. 정확한 전체 대사 미확인.","서로 다른 과거 방송이 2025년 무렵 재공유된 묶음. 한 대화로 합치지 않음.","① 수술을 앞둔 시청자 ② 지뢰 사고를 연상시키는 게임 장면·피해 군인.","① 사연 전체와 진행자가 읽은 범위 ② 실제 발언일과 목함지뢰 사건일의 선후관계가 미확인.","[가설] ① 아픈 시청자를 냉대했다 ② 실제 부상을 희화화했다는 해석. 잘못 읽은 뒤 정정했다는 반론도 2차자료에 존재.","[분석자 도출] 문맥·정정·시간 관계 확인 전 피해자 조롱으로 확정하지 않는다. 기준은 잠정 후보.","[2차자료] 커뮤니티에 조롱 비판이 존재하나 원방송·당시 보도와 발언별 비판 주체는 미확인."],"status":"검증 보류","deletedAt":null,"history":[]},"OOPS-027":{"elements":["[보도 인용] 비판 댓글에 “(전)라도인임? 긁혔나 보네?”라고 답함.","2025년 대선 전남 득표율을 조롱한 타인의 게시물을 공유하고 웃음 표시를 붙인 뒤 받은 질문에 응답.","전라도 주민·유권자와 문제를 제기한 댓글 작성자.","공유한 문구는 다른 사람이 쓴 글이다. 본인의 공유 행위·추가 댓글과 원문 작성자를 구분해야 함.","[비판 해석] 정치적 선택을 근거로 지역 전체를 조롱하고 항의를 다시 비웃었다.","[분석자 도출] 정치적 의견 비판을 출신 지역 전체의 열등화·배제로 확대하지 않는다.","[보도] 댓글 작성자가 지역 비하 이유를 물었고, 이후 일부 이용자의 지역 비하 비판이 이어짐."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-028":{"elements":["[2차자료 인용] 회사원의 “쥐꼬리만한 월급”과 자신의 방송 수입을 비교한 발언으로 기록됨.","시청자와 언쟁하던 방송으로 알려졌으나 질문·직전 대화·방송일은 미확인.","언쟁 상대인 시청자와 일반 회사원.","상대가 실제 회사원인지, 어떤 비판에 답했는지, 수입 비교를 일반화했는지 확인 필요.","[2차자료에 나타난 해석] 회사원의 노동·소득을 낮춰 보고 시청자의 비판을 질투로 취급했다.","[분석자 도출] 소득이나 노동 형태를 사람의 가치·비판 자격의 서열로 바꾸는지 검토한다. 잠정 기준.","[2차자료] 위키에 회사원 비하 논란으로 정리됨. 당시 댓글·보도·원방송에서 비판 주체 확인 못함."],"status":"검증 보류","deletedAt":null,"history":[]},"OOPS-029":{"elements":["[미확인] ‘타 스트리머와 시청자 관련 언행’이라는 여러 사건의 요약만 있음.","단일 영상·발언 구간이 특정되지 않아 대화 문맥을 작성할 수 없음.","타 스트리머·시청자라는 범위만 확인. 개별 대상 미확인.","거래 분쟁·합동방송 등 서로 다른 배경이 섞여 있어 먼저 대상 사건을 특정해야 함.","[미확인] 어떤 발언을 어떤 뜻으로 받아들였는지 사건별 구분 필요.","[분석자 도출] [도출 보류] 구체적인 발언과 비판을 특정하기 전 일반적인 비하 기준으로 채우지 않음.","[2차자료] 여러 언행 비판이 모인 문서는 있으나 원자료 행과 대응하는 단일 문제 제기는 미확인."],"status":"검증 보류","deletedAt":null,"history":[]},"OOPS-030":{"elements":["[보도 인용] 박민영: “장애인 할당이 너무 많다”, “눈이 불편한 것을 제외하면 기득권.”","감동란TV에서 김예지 의원의 비례대표 공천·정치 행보를 비판하던 대화.","김예지 의원. 장애인 정치 대표성에 대한 일반화도 포함.","김 의원은 시각장애인 비례대표 의원. 공천·당론 비판과 장애인의 대표성 문제는 분리해야 함.","[비판 해석] 장애로 인한 장벽을 단순화하고 정치 참여를 특혜로 폄하했다.","[분석자 도출] 정치적 견해 비판에 장애를 인격적 공격·참여 자격 박탈의 근거로 사용하지 않는다.","[보도] 김예지 의원·시민단체·정치권 인사가 인권 감수성 훼손과 장애 비하를 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-031":{"elements":["[보도 요약] 우영우 캐릭터의 반복하는 말투·몸짓을 부부 상황극에 사용. 개별 대사 미확인.","‘이상한 와이프 우와소’라는 패러디 쇼츠. 장애 특성과 유사한 연기가 웃음 장치가 됨.","직접 모방 대상은 허구 인물 우영우. 간접 영향 대상은 자폐인.","우영우는 자폐 스펙트럼 장애가 있는 인물. 캐릭터 연기와 장애 특성의 모방이 겹치는 지점이 쟁점.","[비판 해석] 자폐 특성을 희화화했다. 제작자는 특정 캐릭터의 패러디이며 장애 비하가 아니라고 반박.","[분석자 도출] 모방한 특성이 장애와 연결되는지, 그 특성 자체를 조롱의 대상으로 삼는지 살핀다.","[보도] 일부 시청자·장애 관련 매체에서 자폐인 희화화라고 비판. 과잉 비판이라는 반응도 존재."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-032":{"elements":["[보도 요약] 김지영이 필리핀 결혼이주여성 ‘니퉁’의 어눌한 한국어 말투로 대화.","쯔양의 베트남 음식 먹방에 코미디언이 캐릭터로 출연한 2024년 영상.","필리핀 결혼이주여성을 표상하는 캐릭터와 그 집단.","‘니퉁’은 실제 이주여성이 아니라 코미디언의 연기. 억양·가정 역할을 외국 여성의 전형으로 제시함.","[비판 해석] 이주여성의 언어와 처지를 웃음거리로 만들고 국적 고정관념을 재생산했다.","[분석자 도출] 국적·언어 능력의 차이 자체를 열등하거나 우스운 특성으로 묘사하는지 확인한다.","[보도] 필리핀 시청자 등 일부 구독자가 인종·국적 차별이라고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-033":{"elements":["[보도 요약] 박위의 남동생이 형의 생리현상과 송지은의 도움 약속을 축사에 포함.","결혼식에서 신부를 믿음직한 가족으로 소개하는 취지로 사적인 돌봄 일화를 공개.","박위·송지은. 축사에서 부부 관계와 돌봄 역할을 설명.","박위의 장애·일상 지원 필요성과 신부의 돌봄 역할이 해석 배경. 사적 대화 공개 동의 범위는 미확인.","[비판 해석] 신부를 간병인처럼 묘사하고 사적 일화를 공개했다. 지지·가족애 표현이라는 반론도 있음.","[분석자 도출] 축사·공개 일화가 당사자의 존엄과 사생활을 침해하거나 배우자를 돌봄 역할로 한정하는지 살핀다.","[보도] 일부 누리꾼이 신부·가족의 입장을 고려하지 않은 축사라고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-034":{"elements":["[보도 인용] 프리지아: “내 남자친구가 갤럭시를 쓴다면 약간 싫을 것 같다.”","네일숍 지인의 남자친구 휴대전화와 사진 취향을 이야기하는 브이로그.","직접 대상은 가정한 연인·휴대전화 기종. 모든 이용자를 직접 지칭한 것은 아님.","브랜드 선호·사진 취향 대화라는 조건. 휴대전화 이용자의 경제력·인격을 뜻한다는 사실은 확인되지 않음.","[비판 해석] 특정 기종 사용자·지인을 무시했다. 개인 취향 표명일 뿐이라는 반론도 보도됨.","[분석자 도출] 개인 취향과 이용자에 대한 가치 평가를 구분하고 문장 범위 이상으로 집단 비하를 확장하지 않는다.","[보도] 일부 누리꾼은 무례·편견이라고 비판했고 다른 누리꾼은 취향의 자유라고 반박."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-035":{"elements":["[보도 요약] 박슬기가 영화 촬영 당시 익명 배우가 자신의 매니저를 때렸다는 경험담을 말함.","‘A급 장영란’에서 과거 현장 일화. 피해 진술 속 배우의 말은 박슬기의 재인용.","일화의 익명 배우·매니저. 시청자 추측으로 지목된 배우들은 별개.","출연작·촬영 시기 단서가 실존 배우 추측에 사용됨. 지목된 일부 배우는 무관하다고 해명.","[보도된 결과] 익명 경험담이 특정 배우의 갑질 폭로로 받아들여져 오인·추측이 확산.","[분석자 도출] 피해 경험을 부정하지 않되 익명 단서로 특정인을 가해자로 확정하지 않는다.","[보도] 일부 시청자가 배우를 추측했고 지목된 이지훈 등이 부인. 발언 자체를 비판한 구체적 주체는 미확인."],"status":"문제 제기 보완","deletedAt":null,"history":[]},"OOPS-036":{"elements":["[2차자료 인용] 주르르: “1년 반이면 시간 진짜 빨리 지나가겠다.”","지인의 동생 전역과 군 복무 기간·급여를 시청자 채팅과 이야기하던 방송.","군 복무 중이거나 마친 사람들의 복무 경험.","발언 당시 복무 기간·계급별 급여와 관찰자의 시간 감각이 다르다. ‘월급 200’ 표현의 조건도 확인 필요.","[2차자료의 비판 해석] 복무의 고충을 쉽게 본다. 지인 소식에 대한 시간 감상이라는 반론 가능.","[분석자 도출] 외부 관찰자의 시간 감상과 복무 당사자의 부담 평가를 구분한다. 잠정 기준.","[2차자료] 일부 커뮤니티에서 복무 현실에 대한 무지라는 비판. 당시 독립 보도는 미확인."],"status":"검증 보류","deletedAt":null,"history":[]},"OOPS-037":{"elements":["[2차자료 요약] 고누리의 ‘던파하는 선임’ 영상과 후속 방송이 던파 이용자 비하로 문제 제기됨.","특정 선임의 행동을 그린 애니메이션 및 제목·썸네일. 정확한 대사 미확인.","직접 대상은 영상 속 선임. 던전앤파이터 이용자 전체로 확장됐는지가 쟁점.","게임 이용자에 대한 기존 낙인과 게임명·썸네일의 결합. 제작자는 선임 비판이 목적이라고 설명한 것으로 기록.","[2차자료의 비판 해석] 개인의 문제를 특정 게임 이용자 집단의 특성으로 만든다.","[분석자 도출] 개인의 비매너 행위를 취미 집단 전체의 열등함으로 일반화하는지 확인한다. 잠정 기준.","[2차자료] 이용자 항의·제작사 수정 요청이 기록돼 있으나 공식 요청 원문·당시 발언은 미확인."],"status":"검증 보류","deletedAt":null,"history":[]},"OOPS-038":{"elements":["[보도 인용·요약] ① 생존자를 ‘오줌 동호회’에 빗댄 발언 ② 여성 비하 표현. ② 정확한 문구 미확인.","2014년 팟캐스트 ‘옹달샘의 꿈꾸는 라디오’ 발언이 2015년 재조명. 서로 다른 구간.","① 삼풍백화점 붕괴 생존자 ② 여성. 두 대상을 합치지 않음.","① 재난 속 생존을 위한 행동을 취미처럼 비유했다는 배경 ② 별도 성별 일반화 문구·맥락 확인 필요.","[비판 해석] ① 극한의 생존 경험을 조롱 ② 여성 일반을 저속하게 비하. 발언별 구분 필요.","[분석자 도출] 생존 행동을 오락 취향으로 왜곡하거나 성별 전체를 모욕하는지 각각 확인한다.","[보도] 생존자가 모욕감을 이유로 고소. 여성 비하·옹달샘 방송에 대한 대중 비판도 보도됨."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-039":{"elements":["[가사 요약] 여성과 산부인과 진료를 성적 과시에 연결한 랩 가사. 가사 원문은 재인용하지 않음.","2015-07-10 ‘쇼미더머니4’ 랩 대결에서 나온 가사.","여성 및 산부인과·의사라는 직업 영역.","산부인과 진료는 질병 예방·여성 건강을 위한 의료행위라는 점을 의사회가 비판 근거로 제시.","[비판 해석] 진료를 성적 이용 가능성에 빗대 여성과 의료행위를 모욕했다.","[분석자 도출] 의료행위·여성의 신체를 성적 정복의 비유로 소비하는지 살핀다.","[보도] 대한산부인과의사회가 여성 모욕·의사 명예 훼손을 지적하며 공식 항의."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-040":{"elements":["[보도 인용] 유희열이 앞자리 여성 관객에게 “다리를 벌려 달라”고 말함.","2015년 토이 콘서트에서 공연에 힘을 받게 해 달라는 맥락의 성적 농담.","앞자리에 앉은 여성 관객.","출연자의 평소 ‘감성 변태’ 캐릭터와 공연 분위기를 근거로 친숙한 농담이라는 반론이 있었음. 개인별 동의는 미확인.","[비판 해석] 관객의 신체를 성적 자극 대상으로 삼는 요구. 현장에서는 수용됐다는 반론도 보도.","[분석자 도출] 친밀한 공연 분위기만으로 관객의 성적 대상화에 대한 동의를 가정하지 않는다.","[보도] 일부 관객·누리꾼의 불편과 성적 농담 비판. 공연 내 농담이라는 반론 병존."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-041":{"elements":["[보도 인용] 이윤석: “야당은 전라도당이나 친노당이라는 느낌이 있다.”","정치 토론 프로그램에서 특정 야당에 대한 인상과 지지 성향을 설명.","당시 야당과 전라도 주민·친노 정치 세력.","‘전라도당’은 정당을 지역으로 환원하는 말로 받아들여짐. 정치 분석과 지역 비하의 경계가 쟁점.","[비판 해석] 야당을 지역 편견으로 규정한다. 정치인도 사용한 표현이라는 옹호도 보도됨.","[분석자 도출] 지역 지지 기반 설명과 주민 전체를 폄하하는 의미를 구분해 검토한다.","[보도] 발언에 대한 일부 시청자 비판과 방송 하차 요구. 정치적 의견이라는 옹호도 존재."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-042":{"elements":["[보도 인용] 안중근 사진을 본 퀴즈에서 지민이 “긴또깡?”이라고 말함.","설현과 역사 인물을 맞히던 상황에서 오답·힌트·농담이 이어짐.","사진 속 안중근 의사. 설현의 오답과 지민의 표현을 구분.","안중근은 이토 히로부미를 사살한 독립운동가. ‘긴또깡’이라는 별칭의 대상은 별도 인물이라는 지식이 필요.","[비판 해석] 단순한 무지보다 독립운동가를 대하는 장난스러운 태도가 부적절하다는 해석.","[분석자 도출] 역사 지식 오류와 역사 인물에 대한 조롱·태도 평가를 구분한다.","[보도] 일부 누리꾼이 ‘긴또깡’ 표현과 태도를 비판. 과도한 마녀사냥을 경계하는 반론도 있음."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-043":{"elements":["[보도 요약] 특정 여성 BJ를 보며 자위한 적 있는지 묻고 ‘당연하지’라고 답함.","외질혜→남순, 남순→감스트 순으로 이어진 합동 생방송 게임.","자리에 없는 실존 여성 BJ들.","‘당연하지’는 질문에 무조건 긍정하는 게임 규칙. 사실 인정과 게임 응답을 구분해야 함.","[비판 해석] 타인을 성적 자극의 대상으로 공개적으로 소비했다. 실제 행위 고백인지는 별개.","[분석자 도출] 게임 규칙을 이유로 제3자의 성적 대상화를 허용하거나 사실처럼 단정하지 않는다.","[보도] 시청자·온라인 여론에서 성희롱성 질문·답변을 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-044":{"elements":["[보도 인용] 철구: “박지선은 꺼지세요.” 이후 박미선을 말하려 했다고 설명.","다른 BJ가 자신의 외모를 홍록기에 빗대자 여성 코미디언 이름으로 되받은 생방송.","직접 언급된 고 박지선. 해명에서 새로 지칭한 박미선은 별도.","박지선 사망 직후 시점이 비판을 키움. 박미선으로 대상을 바꿔도 외모를 낮춰 쓰는 구조는 남음.","[비판 해석] 고인 모독 및 두 여성의 외모 비하.","[분석자 도출] 다른 사람의 외모·죽음을 상대를 모욕하는 도구로 쓰는지 확인한다.","[보도] 시청자들의 고인 모독·외모 비하 지적. 박미선도 자신의 외모 지적에 불쾌감을 표명."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-045":{"elements":["[보도 인용] 이경실: “가슴골에 물을 흘려서 … 받아먹으면 … 약수다.” 중간 생략.","‘컬투쇼’ 보이는 라디오에서 이제훈의 상반신 스틸컷을 보며 한 농담.","배우 이제훈의 신체.","별도 사건 배경 없이 사진과 발언으로 핵심 쟁점 이해 가능. 공식 유튜브 영상에는 문제 발언이 직접 담기지 않았다는 보도도 있음.","[비판 해석] 배우의 몸을 성적으로 소비한다. 과민 반응이라는 반론도 보도됨.","[분석자 도출] 성별과 관계없이 상대의 신체를 성적 욕망의 공개 소재로 삼는지 살핀다.","[보도] 일부 청취자가 성희롱성 발언이라고 지적했고 일부는 농담으로 옹호."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-046":{"elements":["[보도 인용] 광고 속 가족 인물: “군대 가면 다리 아플 텐데 마사지기라도 좀 가져갈래?”","입대를 앞둔 인물과 가족의 상황극에서 안마기를 홍보. 실제 군인 인터뷰가 아님.","입대자·장병을 형상화한 허구 인물. 최근 사건 피해자와 연결돼 해석됨.","2024년 훈련병 사망 사건 직후 공개. 대사와 당시 군 인권 이슈의 시간적 중첩이 쟁점.","[비판 해석] 장병 고통과 사망 사건을 연상시키는 내용을 광고 농담으로 소비했다.","[분석자 도출] 실제 사건을 겨냥한 의도와 시기상 연상을 구분하되, 피해를 가볍게 보이게 하는 표현을 살핀다.","[보도] 일부 시청자가 훈련병 사망 사건이 공론화된 때 군인·유가족에 무신경하다고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-047":{"elements":["[보도 인용] 곽튜브가 이나은에게 “오해해서 미안하다”고 말함.","함께한 이탈리아 여행에서 과거 의혹 때문에 차단했던 일을 이야기하며 개인적 사과.","이나은. 발언이 영향을 미치는 별도 대상은 과거 따돌림을 호소한 당사자.","학창 시절 학폭 의혹과 그룹 내 따돌림 의혹은 서로 다른 사안. 한 사안의 해소를 다른 사안의 결론으로 옮기면 안 됨.","[비판 해석] 제3자가 피해 당사자를 대신해 용서·면책하는 장면으로 받아들여짐.","[분석자 도출] 개인적 오해 해소와 타인이 제기한 피해 의혹의 해소를 구분한다.","[보도] 일부 시청자가 ‘대리 용서’라고 비판. 의혹의 진위와 논란의 존재는 별개."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-048":{"elements":["[보도 인용] 윤성빈: “돈이 없어서냐, 막 써서냐.”","독립을 못 하는 이유가 돈이라는 스태프에게 절약을 이야기함. 스태프는 월급·주거비를 설명.","대화 중인 스태프의 소비·독립 문제.","고정 주거비와 가처분소득을 확인해야 개인의 낭비 여부를 판단할 수 있음. 해당 스태프의 실제 가계 자료는 미확인.","[분석 가설] 경제적 제약을 개인의 소비 습관 탓으로 단순화한다는 의미로 읽힐 수 있음.","[분석자 도출] 개인의 경제 사정을 모른 채 빈곤·주거 어려움을 절약 부족으로 단정하는지 살핀다. 잠정 기준.","[확인 한계] 스태프의 ‘논란의 발언’ 반응과 기사는 확인. 독립적인 시청자 비판의 구체적 내용은 미확인."],"status":"문제 제기 보완","deletedAt":null,"history":[]},"OOPS-049":{"elements":["[보도 인용] 빠니보틀: “질질 싸네, 아주 그냥.” 앞 장면에서는 마늘을 안 먹는 이유를 성적으로 암시하는 농담.","여성 출연자들과 함께한 여행 술자리. 곽튜브가 탄산수를 흘리자 말하고 곽튜브는 표현을 자제해 달라고 반응.","직접 대상은 곽튜브의 동작. 동석자·공개 시청자에게 성적 농담으로 수용됨.","영상은 2022-06-19 공개. 별도의 ‘3루론’ 논란과 다른 사건. 웃음 반응만으로 성적 농담의 동의를 확정할 수 없음.","[비판 해석] 초면인 여성 출연자 앞에서 부적절한 성적 표현을 했다는 비판. 단순한 쏟음 묘사·과민 반응이라는 반론도 보도.","[분석자 도출] 중의적 말의 의미·상대 관계·공개 범위를 확인하고 성적 의도를 문구만으로 확정하지 않는다.","[보도] 에펨코리아·더쿠·유튜브 등의 일부 댓글이 성적 농담·저급한 표현을 비판. 옹호 댓글도 존재."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-050":{"elements":["[보도 요약] 팝핀현준이 협찬 항공권 좌석과 서비스에 불만을 SNS에 게시.","해외 공연 출국 과정에서 비즈니스석이 아닌 좌석 제공 등에 항의.","항공사·공연 주최 측의 협찬·조치.","실제 항공권 마련 주체와 약정 좌석이 무엇인지가 중요. 당사자는 뒤늦게 협찬 경위를 알았다고 설명.","[비판 해석] 무상 지원을 받으면서 과도한 대우를 요구했다는 해석.","[분석자 도출] 약속된 서비스에 대한 정당한 항의와 사실 확인 없는 특권적 요구를 구분한다.","[보도] 일부 누리꾼이 협찬 제공자에게 보인 태도를 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-051":{"elements":["[보도 인용] 허니제이: “댄스냐 XX지.” 기사에 비속어를 가린 형태로 인용됨.","‘월드 오브 스우파’ 관련 다른 댄서·크루의 무대를 보는 리액션 영상.","상대 크루의 댄서와 춤.","댄스 경연·경쟁 관계라는 배경은 있으나 성적 비유 자체의 의미는 대화로 이해 가능.","[비판 해석] 전문적 춤을 성행위처럼 표현해 댄서를 모욕·대상화했다.","[분석자 도출] 무대 비평을 신체·성행위에 빗댄 인격적 조롱으로 바꾸는지 본다.","[보도] 일부 누리꾼이 상대 댄서에 대한 무례함과 성적 막말을 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-052":{"elements":["[보도 요약] 성한빈이 방지턱을 넘을 때 내는 소리를 재현하고 ‘우리끼리 쓰는 밈’이라 설명.","‘꼰대희’에서 석매튜가 차를 탈 때의 습관을 소개한 뒤 성한빈이 반응.","직접 대상은 운전 상황의 자기 반응. 여성의 성적 반응을 흉내 냈다는 해석이 쟁점.","사용한 밈·발음의 구체적 성적 용례는 기사에서 충분히 제시되지 않음. 재현 음성·맥락 별도 확인 필요.","[보도된 해석] 일부 시청자가 여성 신음·성적 표현을 연상하는 리액션으로 받아들임. 본인은 성적 의도를 부인.","[분석자 도출] 밈의 통용 의미와 대화 속 사용을 확인하고 소리만으로 성적 의도를 확정하지 않는다.","[보도] 일부 누리꾼의 성적 의도·부적절한 리액션 지적."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-053":{"elements":["[보도 인용] 김민수가 여성 셰프에게 “우리 같이 데이트하자”고 말함.","‘피식대학’에서 부재중인 김시현 셰프를 언급하며 연락·데이트 이야기를 함.","김시현 셰프. 자신의 전문성과 별개로 연애 대상으로 언급됨.","셰프가 해당 대화에 직접 참여하지 않았다는 조건. 나이 차이 자체는 비판의 충분한 근거가 아님.","[비판 해석] 요리 실력·직업 활동 대신 이성 교제 대상으로만 대하며 부담을 줬다.","[분석자 도출] 참여하지 않은 제3자에게 공개적으로 연애·연락 압력을 만들거나 전문성을 지우는지 살핀다.","[보도] 일부 누리꾼이 여성 셰프를 데이트 상대로 취급한 무례함을 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-054":{"elements":["[보도 인용] 엄은향: “유튜버는 어그로 끌어야 된다”, “얼굴 나온다고 말한 적 없다.”","임성한 작가 라이브 출연 예고 뒤 실제로는 전화 연결만 진행돼 항의가 나온 상황.","방송을 기다린 시청자와 콘텐츠 예고의 정확성.","사전 홍보 문구와 실제 출연 방식·기다린 시간의 차이가 핵심 외부 자료.","[비판 해석] 기대를 유도한 뒤 시청자를 탓하거나 기만을 합리화한다는 의미로 읽힘. 당사자는 분위기를 풀려는 농담이라 설명.","[분석자 도출] 홍보 약속과 실제 제공 내용의 차이를 확인하고 시청자 항의를 조롱·회피하는지 본다.","[보도] 일부 시청자가 출연 방식·구성과 대응 태도를 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-055":{"elements":["[보도 요약] 도쿄규짱이 귀국 사실을 알리지 않고 일본 거주자 시점의 콘텐츠를 계속했다고 설명.","한국 거주 사실이 알려진 뒤 초기 해명·사과 영상을 게시.","구독자와 ‘일본 현지 생활’이라는 채널의 정보 신뢰성.","실제 거주 시기와 촬영·게시 시기의 차이가 필요. 방문 촬영 자체가 허위인 것은 아님.","[비판 해석] 현재 일본에 사는 현지인의 정보라는 인상을 지속해 시청자를 오인시켰다.","[분석자 도출] 콘텐츠가 내세운 현지성·시점과 실제 조건이 중요한 차이를 보이는지 확인한다.","[보도] 일부 구독자가 귀국 사실을 숨긴 점을 기만·신뢰 훼손으로 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-056":{"elements":["[보도 인용] 김구라가 성매매 여성들의 버스 이동을 “정신대”에 빗댐.","2002년 인터넷 라디오에서 집창촌 여성들의 단속 항의 시위를 이야기. 2012년 재조명.","일본군 ‘위안부’ 피해자와 성매매 여성.","전시 강제 동원·성폭력 피해와 당시 성매매 여성의 항의 시위는 다른 맥락.","[비판 해석] 강제적 피해 경험을 성매매와 동등하게 놓아 역사적 피해자를 모욕했다.","[분석자 도출] 강제 피해와 다른 사안을 비유할 때 피해 사실·존엄을 지우는 등치가 생기는지 확인한다.","[보도] 과거 발언이 위안부 피해자 비하로 비판받아 재공론화됨."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-057":{"elements":["[보도 인용] 송대관: “고난을 겪고 있다”, “세월이 약.”","라디오에서 자신의 경제적 어려움을 회고하다 수사받던 후배 김호중을 위로.","김호중과 당시 사건의 책임.","당시 김호중은 음주 뺑소니·운전자 바꿔치기 혐의로 수사를 받는 상황. 사후 판결과 당시 상황을 혼동하지 않음.","[비판 해석] 행위 책임을 개인적 불운·고난처럼 묘사해 희석했다.","[분석자 도출] 사람에 대한 위로와 문제 행위의 정당화·책임 축소를 구분한다.","[보도] 일부 누리꾼이 ‘범법자 옹호’라고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-058":{"elements":["[보도 인용] 이홍기: “성매매가 아니면 책임질 수 있어?”","최민환 관련 의혹 뒤 팬 커뮤니티에서 비판 팬에게 반문.","직접 대상은 팬의 주장·책임. 간접 대상은 최민환 관련 의혹.","당시 의혹의 내용·확인 수준과 본인의 동료 관계가 해석에 중요. 의혹은 확정 사실이 아님.","[비판 해석] 의혹 해소 전 동료를 일방적으로 두둔하고 팬의 문제 제기를 압박했다.","[분석자 도출] 미확인 의혹의 신중한 검증 요구와 비판자 위협·책임 전가를 구분한다.","[보도] 일부 팬들이 동료 옹호와 팬을 향한 반문을 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-059":{"elements":["[보도 인용] JK김동욱: “애들 야구하면서 나온 해프닝을 이렇게 키운다고?”","배재고 야구부 응원 구호 논란·교육청 조사 기사를 SNS에 공유하며 평가.","문제 된 응원 구호와 이를 조사·비판하는 측.","구호가 5·18 관련 탱크 이미지·광주를 조롱한 것으로 해석된 배경이 필요. JK김동욱이 구호의 원발언자는 아님.","[비판 해석] 역사적 피해와 지역 비하 문제를 사소한 장난으로 축소한다. 과도한 조사라는 반대 관점도 있음.","[분석자 도출] 사건 평가에서 축소한 피해·역사적 함의가 무엇인지 확인하고 원행위자와 논평자를 구분한다.","[보도] 역사적 사건을 연상시키는 구호 및 이를 해프닝으로 다룬 태도에 비판 제기."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-060":{"elements":["[보도 인용] 스윙스: “사람은 변한다.”","소속 래퍼 양홍원의 앨범 홍보 글에 학폭을 지적한 댓글이 달리자 응답.","양홍원에 대한 과거 의혹·현재 평가와 비판 댓글 작성자.","소속사 대표와 소속 가수의 관계. 당시 학폭 의혹의 확인 범위와 반성·변화에 대한 근거가 별도로 필요.","[비판 해석] 피해 책임보다 변화 가능성을 앞세워 동료를 감쌌다. 확인되지 않은 비난을 경계한다는 취지도 제시.","[분석자 도출] 변화 가능성을 인정하는 말과 피해 경험·책임을 지우는 말을 구분한다.","[보도] 한 누리꾼이 학폭 가해 의혹이 있는 가수의 홍보를 비판했고 스윙스가 반박."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-061":{"elements":["[보도 인용] 김갑수: “사춘기 성장 과정의 일부”, “피해자가 별로 불쌍하거나 그렇지 않다.”","‘매불쇼’에서 남주혁의 미확정 학폭 의혹과 배우 평가 기준을 논함.","피해를 주장하는 사람과 의혹 대상인 남주혁.","당시 양측 주장이 대립하고 사실관계가 확정되지 않았음. 사후 수사 결과를 발언 당시의 전제로 넣지 않음.","[비판 해석] 폭력·피해 호소를 정상적 성장 과정이나 과장으로 치부했다.","[분석자 도출] 의혹 검증의 필요성을 말하며 피해 호소 자체를 근거 없이 사소화·불신하는지 본다.","[보도] 피해 경시 발언으로 논란. 진행자도 학교폭력이 단순한 성장 과정인지 반문."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-062":{"elements":["[보도 인용] 김갑수: “연예인 하면 왜 안돼?”라는 취지로 황영웅의 활동 가능성을 옹호.","‘매불쇼’에서 황영웅의 폭력 전력·여러 의혹과 방송 하차를 토론.","황영웅의 연예 활동, 폭력 피해와 비판 여론.","확인된 전력과 추가 의혹은 구분 필요. 세대별 폭력 감수성이 다르다는 주장이 함께 나옴.","[비판 해석] 세대·성장 배경을 이유로 폭력의 심각성과 피해를 낮춰 보았다.","[분석자 도출] 배경 설명이 폭력을 정상화하거나 피해자보다 가해자의 복귀만 우선하는지 검토한다.","[보도] 일부 패널·보도가 피해자 관점 부재와 옹호 논리를 문제 삼음."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-063":{"elements":["[보도 인용] 김갑수: “저는 박수홍 씨를 나무라고 싶다”, “돈 찾으면 되는 일.”","‘매불쇼’에서 친형과의 금전 분쟁을 가족 간 돈 배분·독립 문제로 설명.","박수홍의 대응과 가족 간 금전 분쟁.","당시 횡령 관련 고소·민사 분쟁의 진행 단계가 중요. 이후 구속·판결을 당시의 확정 사실로 사용하지 않음.","[비판적 해석·분석] 피해 호소를 단순한 돈 배분과 개인 판단 미숙으로 축소한다. 본인은 가족주의에서 벗어나 자기 삶을 책임져야 한다는 취지를 제시.","[분석자 도출] 피해 당사자의 선택 비판이 상대의 책임을 지우거나 피해를 단순화하는지 살핀다.","[확인 한계] 발언 보도는 확인. 이 발언을 비판한 구체적 시청자 원문·주체는 확보하지 못함."],"status":"문제 제기 보완","deletedAt":null,"history":[]},"OOPS-064":{"elements":["[보도 요약] 김갑수가 고 김새론 관련 의혹을 개인의 특성·이른 사회화 등의 문제로 설명.","‘매불쇼’에서 김수현·김새론의 미성년 시기 교제 의혹을 다룬 2025-03-17 방송.","고 김새론과 미성년 시기의 성적 관계 의혹.","당시 교제 시기·금전 관계는 다툼 중인 주장. 미성년기라는 조건과 고인의 반박 불가능성이 중요.","[비판 해석] 미성년자 보호 문제를 개인 특성으로 돌리고 고인에게 모욕적 평가를 가했다.","[분석자 도출] 검증되지 않은 성적 의혹을 개인의 성향으로 정당화하거나 고인을 깎아내리는지 확인한다.","[보도] 시청자 비판이 제기됐고 진행자도 부적절한 방송이었다고 인정."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-065":{"elements":["[보도 인용] 김호영: “아사리판은 옛말, 지금은 옥장판.”","뮤지컬 ‘엘리자벳’ 캐스팅 논란 무렵 SNS에 게시.","문구상 명시적 대상 없음. 일부 독자는 옥주현을 대상으로 추정.","캐스팅 시기·‘옥’이라는 말의 유사성이 특정인을 연상시킨 배경. 저격 의도는 당사자 측이 부인.","[수용 해석] 옥주현을 암시적으로 비난한 글로 읽혔다. 실제 지칭·의도는 미확정.","[분석자 도출] 말장난·시점만으로 특정인 지칭을 확정하지 않고 직접 확인·반론을 함께 본다.","[보도] 뮤지컬 팬들의 저격 추측과 당사자 간 분쟁이 발생. 비하가 확정됐다는 뜻은 아님."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-066":{"elements":["[보도 요약] 옥주현이 김호영에게 사과받지 못했고 고소 취하를 후회한다는 취지로 말함.","2026년 팬 소통에서 2022년 ‘옥장판’ 분쟁을 다시 이야기.","김호영과 당시 갈등 해결·사과 여부.","2022년 고소·취하 경위 및 양측의 서로 다른 설명을 확인해야 함. 사과가 없었다는 것은 일방의 주장.","[분석 가설] 해결된 것으로 보이던 분쟁을 일방적으로 재점화한다. 자신의 경험 설명일 수도 있음.","[분석자 도출] 당사자 간 사실관계가 다른 사적 분쟁을 확정 사실처럼 전달하는지 살핀다. 잠정 기준.","[확인 한계] 발언·재보도는 확인. 재언급 자체를 누가 왜 문제 삼았는지 구체적 비판은 부족."],"status":"문제 제기 보완","deletedAt":null,"history":[]},"OOPS-067":{"elements":["[보도 인용] 신동엽: “소극장 뮤지컬은 마이크를 안 차도 된다.”","‘짠한형’에서 붐·넉살 등과 대학로 공연을 이야기하며 소극장·뮤지컬을 단정적으로 설명.","대학로 소극장 뮤지컬과 배우·제작진의 활동.","대학로의 실제 뮤지컬 제작 현황·음향 사용이 주장 검증에 필요. 공연장 크기로 장르 존재·전문성을 단정할 수 없음.","[비판 해석] 현장을 모르면서 뮤지컬이 거의 없거나 준비 수준이 낮은 듯 묘사했다.","[분석자 도출] 공연 분야의 실태를 확인하고 규모를 전문성·가치의 낮음과 연결하는지 살핀다.","[보도] 관객·종사자로 소개된 댓글들이 뮤지컬의 존재와 창작자의 노력을 무시한다고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-068":{"elements":["[보도 인용] 송진우: 한국과 일본이 과거에 “싸웠다”고 설명.","다문화 자녀에게 한일 역사를 어떻게 설명할지 이야기한 ‘354 삼오사’ 대화.","일제강점기의 한국·일본 관계와 자녀 역사교육.","식민 지배·침략이라는 비대칭 관계가 핵심 배경. 자녀가 겪을 차별에 대한 부모의 우려도 발언 취지에 포함.","[비판 해석] 침략·지배를 대등한 쌍방 다툼으로 축소했다. 당사자는 아이 눈높이 설명을 의도했다고 해명.","[분석자 도출] 쉬운 설명을 위해 역사적 행위 주체·피해 관계를 지우는지 살핀다.","[보도] 일부 시청자가 역사 왜곡·침략 사실 축소를 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-069":{"elements":["[보도 인용] 알베르토: “양쪽 얘기도 들어봐라.”","‘354 삼오사’에서 다문화 자녀 교육과 한일 역사에 대한 설명을 이야기.","한일 역사 해석과 자녀에게 권할 태도.","식민 지배에 관한 확인된 역사 사실과 해석의 다양성은 다름. 일반적인 다각도 이해 조언인지 적용 범위가 중요.","[비판 해석] 식민 지배의 책임을 양비론으로 흐린다. 제작진은 다양한 관점 이해를 위한 일반론이라고 설명.","[분석자 도출] 여러 관점 청취가 확인된 피해·책임을 상대화하는 의미인지 문맥을 확인한다.","[보도] 일부 시청자가 식민지 역사에 양비론을 적용했다고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-070":{"elements":["[보도 요약] 이나연이 JTBC 사옥의 에어컨이 나오지 않는다며 회사 사정과 연결한 농담.","출근 브이로그에서 사내 환경·더위를 이야기.","JTBC의 냉방·경영 상황.","사옥 냉방 실제 운영과 회사 재정 사정은 다른 사실. 앵커는 냉방이 정상 작동한다고 반박.","[비판 해석] 개인 체감을 회사 전체의 운영·재정 상태로 확대해 부정확한 인상을 줬다.","[분석자 도출] 부분 경험을 조직 전체의 재정·운영 문제로 일반화할 때 근거가 있는지 확인한다.","[보도] 일부 시청자가 경솔함을 지적했고 JTBC 앵커가 냉방 관련 내용을 공개 반박."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-071":{"elements":["[보도 인용] 이광길: “그거 알아? 황재균 이혼한 거.”","야구 중계의 광고 시간 사담이 유튜브 보이는 라디오로 송출.","황재균·지연의 혼인 상태.","전해 들은 말에 근거했으며 당시 지연 측은 사실무근이라고 반박. 이후 상황은 당시 정보 검증과 구분.","[보도된 쟁점] 확인되지 않은 연예인·선수의 사생활을 사실처럼 공개했다.","[분석자 도출] 사생활 정보의 출처·확인 수준을 밝히고 전언을 확정 사실로 전달하지 않는다.","[보도] 당사자 측이 이혼설을 부인했고 잘못된 소문 확산이 문제로 다뤄짐."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-072":{"elements":["[보도 인용] 심수봉: “노래가 뭔지, 삶이 뭔지도 모르는 아가씨인 것 같다.”","축제에서 김다현 다음 순서로 무대에 올라 직전 공연과 가수를 공개 평가.","후배 가수 김다현의 노래·삶의 경험.","김다현은 당시 17세 후배. 공연 순서·선후배 관계가 공개 평가의 압력과 연결됨.","[비판 해석] 음악 비평을 넘어 어린 후배의 인격·삶을 공개적으로 낮춰 봤다.","[분석자 도출] 작품·가창 비평과 사람의 삶·자격을 모욕하는 평가를 구분한다.","[보도] 일부 시청자·누리꾼이 어린 후배에게 지나친 발언이라고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-073":{"elements":["[보도 인용] 영빈: “백신 안 맞아도 나는 코로나 안 걸릴 거 같다.”","팬 라이브에서 백신 접종·감염 가능성을 자신의 생활 방식과 연결해 이야기.","자신의 감염 위험과 백신 접종의 필요성.","외부 노출을 적게 느낀다는 개인 판단과 감염 위험은 다름. 개인 체험은 예방 효과의 근거가 아님.","[비판 해석] 개인의 막연한 믿음이 백신 불필요·감염 안전이라는 인상을 준다.","[분석자 도출] 개인의 감염 예측을 의학적 사실처럼 단정하거나 대중의 예방 판단에 일반화하는지 살핀다.","[보도] 일부 이용자가 백신·감염에 대한 경솔하고 부정확한 인식이라고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-074":{"elements":["[보도 인용] 침착맨: “그냥 홍명보 감독이 싫어서 그러는 거 아니냐.”","라이브에서 국가대표 감독 선임에 대한 축구 팬들의 반발을 평가.","홍명보 선임을 비판하는 축구 팬들의 동기.","축구협회 감독 선임 절차·공정성에 대한 비판이 있었다는 배경. 단순한 개인 호불호와 다른 근거가 존재.","[비판 해석] 절차 문제 제기를 근거 없는 개인적 미움으로 축소했다.","[분석자 도출] 비판자가 제시한 이유를 확인하지 않고 감정·악의로 환원하는지 살핀다.","[보도] 일부 축구 팬들이 선임 절차에 관한 비판을 무시했다고 반발."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-075":{"elements":["[보도 요약] 일주어터가 김가영을 좋은 사람이라고 두둔하고 비난 댓글을 고인이 원치 않을 것이라고 말함.","오요안나 직장 내 괴롭힘 의혹이 공론화된 시점의 김가영 SNS 댓글.","김가영에 대한 평가·댓글 작성자와 고 오요안나의 의사.","함께한 방송에서의 인상과 직장 내 행위 의혹은 다른 정보. 고인의 의사를 대신 확인할 근거는 없음.","[비판 해석] 제한된 개인 경험으로 의혹을 덮고 고인의 뜻을 대신 말해 유족·문제 제기자를 위축시킨다.","[분석자 도출] 개인적 친분을 사건 무관함의 증거로 쓰거나 고인·피해자의 의사를 추정해 비판을 막는지 본다.","[보도] 일부 누리꾼의 역풍과 유족에게 한 사과가 보도됨. 개별 유족의 비판 문구는 별도 미확인."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-076":{"elements":["[보도 인용] 일주어터: “깡패 집단 같다”, “폐쇄적인 조직 문화.”","‘뉴잼스’ 야구 토크에서 여러 구단을 비교·평가.","한화 이글스 구단의 조직 문화·구성원.","팬덤 토크라는 형식은 있으나 개별 사건을 구단 전체의 속성으로 일반화할 근거가 제시됐는지 별도 확인.","[비판 해석] 구단과 구성원을 범죄 집단 같은 부정적 이미지로 통째로 낙인찍는다.","[분석자 도출] 특정 팀 평가를 근거 없는 집단 모욕·범죄 비유로 바꾸는지 살핀다.","[보도] 프로야구 팬 커뮤니티에서 발언이 부적절하다는 지적."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-077":{"elements":["[보도 인용] 김신영: “우리 방송은 못 나온다”, “현타 제대로 올 것 같다.”","라디오에서 플레이브의 신곡을 들은 뒤 버추얼 아이돌 출연 방식에 대해 대화.","버추얼 아이돌 플레이브와 그 활동 방식.","플레이브는 실제 멤버들의 음악·안무 활동을 아바타로 보여주는 그룹. 순수 자동생성 캐릭터와 다름.","[비판 해석] 낯섦을 이유로 활동을 가볍게 보고 방송 출연 자격을 배제했다.","[분석자 도출] 새로운 형식에 대한 개인적 낯섦과 출연자·팬의 가치·자격을 폄하하는 말을 구분한다.","[보도] 팬 등 일부 청취자가 무례·비객관적 발언이라고 지적하고 하차를 요구."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-078":{"elements":["[보도 인용] 김구라: “나영석, 김태호가 아닌데 인성이 안 좋은 사람들이 대부분이다.”","유튜브에서 유명 PD들의 능력·인성을 다른 PD들과 비교.","방송 PD 직군 일반.","직군의 소통 문제라는 발언 취지와 ‘대부분’이라는 수량적 일반화는 구분해야 함.","[비판 해석] 소수의 유명인을 제외한 PD 대다수를 인성 나쁜 집단으로 규정했다.","[분석자 도출] 일부 경험을 직군 대다수의 인격적 결함으로 일반화할 근거가 있는지 본다.","[보도] 후폭풍이 거셌다는 보도·당사자 설명. 구체적 비판자와 원문 댓글은 미확인."],"status":"문제 제기 보완","deletedAt":null,"history":[]},"OOPS-079":{"elements":["[보도 인용] 김갑수: “이현주 씨는 그런 일 당할 만하더만.”","곽튜브·이나은 논란을 평가하면서 따돌림을 호소한 이현주를 언급.","이현주의 성향·피해 호소.","당시 그룹 내 따돌림 관련 주장·반론이 대립한 배경. 이를 확정하지 않아도 피해 정당화 표현 자체는 검토 가능.","[비판 해석] 따돌림을 당한 이유를 피해자의 특성 탓으로 돌렸다.","[분석자 도출] 피해자가 어떤 사람인지를 근거로 폭력·배제를 당할 만했다고 말하는지 확인한다.","[보도] 보도·일부 시청자가 피해자 책임 전가라고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-080":{"elements":["[보도 인용·요약] ① “출연료는 여자로”라는 취지의 말 ② 장애를 소재로 한 농담. ② 전체 대사 미확인.","KBS ‘아침마당’ 강연에서 돈 대신 받는 출연료·일상 소재를 농담으로 설명.","① 여성의 인격·역할 ② 장애인. 발언별 대상 구분 필요.","공영방송 강연이라는 공개 형식. 장애를 이용한 농담의 구체적 문구·진행 순서는 보완 필요.","[비판 해석] 여성을 보수처럼 교환 대상으로 다루고 장애를 모욕·비하했다.","[분석자 도출] 여성을 물건·보상으로 묘사하거나 장애 특성을 모욕의 장치로 쓰는지 각각 확인한다.","[보도] 장애인차별금지추진연대 등 6개 인권단체가 장애·여성 비하라고 성명으로 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-081":{"elements":["[보도 인용] 민경우: “노인네들이 너무 오래 산다는 거다.” 이어 빨리 사망해야 한다는 말 뒤 ‘죄송하다’고 덧붙임.","보수 성향 유튜브에서 세대교체를 이야기한 2023년 10월 발언이 인선 때 재조명. 스스로 극단적 표현이었다고 설명.","노년층의 생존·정치적 영향력.","발언 직후 사과·세대교체 설명이 있었다는 보도와 이를 생략한 보도에 대한 당의 항의가 존재.","[비판 해석] 고령자의 장수를 문제로 취급한다는 비판. 발언자는 젊은 세대의 역할론을 강조한 실수라고 설명.","[분석자 도출] 정치적 세대교체 비판과 연령집단의 생존 가치 부정 여부를 살피고 즉시 붙인 정정·단서도 반영한다.","[보도] 노인 비하 지적과 사과 요구가 이어짐. 당은 전체 취지 왜곡이라는 반론을 냄."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-082":{"elements":["[보도 요약] 이상경이 소득을 모으고 집값이 떨어질 때 구매 기회가 온다는 취지로 조언.","10·15 부동산 대책 이후 유튜브 인터뷰에서 무주택자의 구매 시점을 이야기.","주택을 사지 못한 사람들의 선택·주거 문제.","당시 주택 가격·대출 규제·소득 제약이 중요. 자신의 주택 거래 논란은 별도 사실 확인 대상.","[비판 해석] 정책으로 인한 제약·주거비 부담을 개인이 기다리고 저축하면 되는 문제로 단순화했다.","[분석자 도출] 정책 책임자의 조언이 실제 제약을 고려하는지 확인하고 사적 투자 의혹과 발언 평가를 구분한다.","[보도] 무주택자의 현실과 동떨어졌다는 비판이 보도됨."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-083":{"elements":["[보도 인용] 복기왕: “15억 정도 아파트면 서민들이 사는 아파트라는 인식이 있다.”","주택 대출 규제와 가격 기준을 설명하는 과정.","15억 원 안팎 아파트 거주자와 ‘서민’의 범위.","15억 기준은 대출 정책 구간과 연결. 당시 소득·주택 분포 없이 국민 전체의 보통 수준으로 단정할 수 없음.","[비판 해석] 대다수 가계의 자산 현실과 동떨어진 계층 인식을 드러냈다.","[분석자 도출] 정책 가격 구간과 생활 수준을 가리키는 말을 혼동하거나 보편화하는지 살핀다.","[보도] 야당 등이 서민 인식이 현실과 다르다고 비판. 발언자는 단어 선택이 부정확했다고 설명."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-084":{"elements":["[보도 인용] 임현택이 장상윤을 향해 “정신분열증 환자 개소리”라고 게시.","의대 증원·의료정책 관련 당국자 발언을 SNS로 비판.","직접 대상은 정책 당국자. 비유에 이용된 대상은 정신질환자.","병명을 상대의 비논리·무능을 뜻하는 욕설처럼 쓴 구조. 의사단체 대표라는 위치도 문제 제기의 배경.","[비판 해석] 정신질환자를 비하하고 환자에 대한 차별·낙인을 조장했다.","[분석자 도출] 질병·장애 명칭을 상대의 인격·능력을 공격하는 욕설로 사용하는지 본다.","[보도] 한국정신장애인연합회 등 단체가 차별·배제 조장이라고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-085":{"elements":["[보도 요약] 오태원이 발달장애인 부모에게 아이를 낳은 일을 탓하는 듯 말함.","발달장애인 부모의 돌봄 어려움이 화제가 된 기자단 자리.","발달장애인과 그 부모의 출산·돌봄 경험.","당사자는 어려움에 공감한 말이었다고 설명. ‘장애를 미리 알았으면’이라는 가정은 확인된 문구가 아님.","[비판 해석] 장애인의 출생을 불행·잘못처럼 보고 부모에게 책임을 돌렸다.","[분석자 도출] 장애 가족의 고충 설명이 장애인의 존재 가치 부정·부모 비난으로 바뀌는지 살핀다.","[보도] 장애인 학부모단체·야당이 규탄하고 사과를 요구."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-086":{"elements":["[보도 요약] 이정엽이 여성 공직자에게 여성스럽다·가녀리다는 등 외모 관련 평가를 함.","도의회 업무 질의 중 격려. 상대가 업무로 칭찬해 달라고 하자 더 웃으면 좋겠다고 덧붙임.","질의에 답하는 여성 공직자.","의원과 피질의 공직자라는 위치 차이. 현장에서 당사자가 업무 중심 평가를 요청함.","[비판 해석] 업무 성과 대신 성별·외모로 평가하고 불편함 표명에도 태도 변화를 요구했다.","[분석자 도출] 공적 업무 관계에서 신체·외모 평가를 하는지, 상대의 경계 표현을 존중하는지 본다.","[보도] 공직자가 현장에서 두 차례 업무로 평가해 달라고 지적. 이후 부적절 발언 비판 보도."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-087":{"elements":["[보도 요약] 이준석이 성적·폭력적 내용을 구체적으로 재현하며 다른 후보에게 질문.","대선 후보 TV 토론에서 타인이 썼다고 주장한 표현의 적절성을 물음.","인용 대상으로 제시한 인물·발언과 전국 TV 시청자.","인용 원문의 진위·화자 귀속은 별도 검증 대상. 정책 토론의 시간·시청층도 쟁점.","[비판 해석] 비판을 위한 인용이라도 불필요하게 성적 폭력을 상세 노출했다.","[분석자 도출] 인용 목적·필요성과 구체적 재현 수준을 함께 보며 원발언에 대한 동의로 오인하지 않는다.","[보도] 여성·시민단체가 언어폭력·아동청소년 시청 영향을 이유로 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-088":{"elements":["[보도 인용] 유세윤: 팔을 구부리면 “X신같아 보인다.”","공연 중 관객에게 팔을 쭉 뻗으라고 유도하며 동작을 비유.","팔을 구부린 관객의 동작과 장애를 연상시키는 모욕어.","공연 뒤 뮤지는 사전에 기획한 콘셉트였다고 설명해 즉흥 발언이라는 초기 설명과 차이가 있음.","[비판 해석] 장애를 우스운·못난 동작의 비유로 사용했다.","[분석자 도출] 신체 특성·장애 명칭을 열등함을 뜻하는 모욕어로 쓰는지 확인한다.","[보도] 장애인 비하라는 문제 제기와 출연자·소속사의 해명이 보도됨."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-089":{"elements":["[보도 요약] 샘 오취리가 학생들의 관짝춤 분장을 인종차별이라고 비판하고 SNS에 사진을 공유.","졸업사진 패러디의 검은 얼굴 분장을 설명하는 글과 영어 해시태그.","패러디한 학생들의 표현과 한국 사회의 인종 인식.","블랙페이스의 차별 역사, 패러디 대상의 문화적 맥락, 학생 식별 가능성·해시태그 용례가 각각 필요.","[상반된 해석] 인종차별 지적이라는 취지와 학생 신상 노출·한국 비하라는 역비판이 함께 존재.","[분석자 도출] 차별을 비판할 권리와 학생 식별정보 노출·집단 일반화·다국어 표현의 의미를 구분한다.","[보도] 일부 이용자가 학생 사진 공개·영어 표현·해시태그를 비판. 당사자는 비하 의도를 부인."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-090":{"elements":["[보도 인용] 정현규: “산수할 줄 알아?”","‘데블스 플랜2’ 연합 플레이 중 최현준이 자신의 전략대로 움직이지 않자 질문.","최현준의 계산·이해 능력.","두뇌 경쟁·전략 게임이라는 형식. 실제 계산 오류 확인과 상대 지능을 낮추는 어투는 구분 필요.","[비판 해석] 게임 협의가 아니라 상대의 능력을 공개적으로 모욕했다.","[분석자 도출] 게임 전략상 압박과 불필요한 능력 비하를 문맥·반복·상대 반응으로 구분한다.","[보도] 일부 시청자가 무례한 말투·행동을 비판했고 출연자도 미숙함을 인정."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-091":{"elements":["[보도 인용] 이해찬: “선천적인 장애인은 의지가 약하다고 한다.”","영입 인재 최혜영을 칭찬하며 선천·후천 장애인을 비교한 유튜브 대화.","선천적 장애인 일반과 비교 대상으로 든 후천적 장애인.","최혜영의 사례를 칭찬하는 취지였으나 장애 발생 시점으로 의지를 일반화할 근거는 별도 필요.","[비판 해석] 특정 장애 집단을 의지가 약한 사람으로 낙인찍는다.","[분석자 도출] 한 사람을 칭찬하기 위해 다른 집단의 의지·인성을 근거 없이 낮추는지 본다.","[보도] 정치권과 장애인 관련 비판이 제기됐고 발언자는 사과."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-092":{"elements":["[보도 인용] 추미애: “외눈으로 보도하는 언론.”","김어준을 둘러싼 언론 비판에 반박하며 편향 보도를 지적한 SNS 글.","직접 대상은 언론의 편향성. 비유에 쓰인 것은 시각·신체 특성.","‘외눈’의 사전적·관용적 뜻과 장애인 비하 용례가 논쟁. 당사자는 실제 장애인을 지칭하지 않았다고 설명.","[비판 해석] 신체적 특성을 부정적 편향성의 말로 사용해 장애 낙인을 만든다.","[분석자 도출] 의도한 비판 대상이 장애인이 아니어도 신체 특성을 열등함의 비유로 쓰는지 검토한다.","[보도] 장혜영·이상민 의원과 장애인권익문제연구소 등이 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-093":{"elements":["[보도 인용·요약] 정봉주가 DMZ 지뢰를 밟는 상황을 목발 경품에 연결해 농담.","2017년 팟캐스트에서 북한 스키장 활용 등을 이야기하다 나온 말이 2024년 재조명.","지뢰 부상 상황과 실제 피해 군인들.","2015년 DMZ 목함지뢰 사건으로 군인들이 중상을 입은 배경. 원발언일은 2017년으로 보도됨.","[비판 해석] 군인의 중대한 부상과 보조기구를 이벤트 경품처럼 희화화했다.","[분석자 도출] 실제 피해와 연결되는 신체 손상을 가벼운 오락·경품으로 전환하는지 본다.","[보도] 피해 군인 관련 비판과 정치권 문제 제기가 보도됨."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-094":{"elements":["[보도 요약] 김한규가 이재명도 피해자가 돼 느낀 점이 있을 것이라는 취지로 평가.","피습 후 이재명의 ‘전쟁 같은 정치 종식’ 메시지를 긍정적으로 평가하는 인터뷰.","피습 피해자인 이재명의 인식 변화.","흉기 피습 사건 직후이며 인용 대상은 퇴원 메시지. 칭찬하려는 취지와 피해를 통한 교훈이라는 함의가 공존.","[비판 해석] 피해 전에는 성찰하지 않았거나 피해를 입어 교훈을 얻어야 했다는 의미로 들릴 수 있음.","[분석자 도출] 범죄 피해를 당사자의 부족함을 고치는 계기·책임처럼 표현하는지 살핀다.","[보도] 당내에서 부적절 발언으로 문제 삼았고 지도부가 경고."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-095":{"elements":["[보도 인용] 김병주: “정신 나간 국민의힘 국회의원들.”","국회 대정부질문에서 국민의힘의 ‘한미일 동맹’ 표현을 비판.","국민의힘 의원들의 인식·정책 표현.","해당 정당 논평의 ‘동맹’과 ‘안보협력’ 표현 차이가 논쟁 배경. 장애 비하인지에 대한 반론도 있음.","[상반된 해석] 무책임한 안보 인식 비판이라는 해석과 모욕·정신장애 비하라는 비판.","[분석자 도출] 정책 비판의 구체적 근거와 정신적 상태를 이용한 모욕의 의미를 구분한다.","[보도] 국민의힘 의원들이 반발. 김예지는 장애인 비하라고 지적하고 이준석 등은 선택적 비판을 반박."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-096":{"elements":["[보도 요약] 딘딘이 벤투호 성적을 비관하고 16강을 바라는 반응을 비꼼.","2022년 월드컵 전 라디오에서 대표팀 전망을 이야기. 대회 성과 뒤 재조명.","벤투 감독·대표팀과 낙관적인 팬들.","원발언은 경기 전 예측. 이후 16강 진출은 사후 정보이며 원래 발언의 공격적 방식과 구분해야 함.","[비판 해석] 단순한 전망을 넘어 선수·감독의 노력을 무시하고 팬의 기대를 조롱했다.","[분석자 도출] 예측이 빗나간 사실과 표현의 근거·모욕성은 따로 평가한다.","[보도] 일부 팬이 성급한 비난과 조롱을 비판. 대회 후 사과·재논란 보도."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-097":{"elements":["[보도 인용] 신동: “난 남자고 넌 여자잖아.”","다이어트 사연을 읽으며 자신과 여성에게 다른 체중 관리 요구를 적용.","여성의 외모·체중 관리 의무.","별도의 사건 배경 없이 남녀에 다른 기준을 적용한 문장 구조로 쟁점 이해 가능.","[비판 해석] 남성의 체중은 허용하면서 여성에게만 외모 관리를 요구한다.","[분석자 도출] 같은 조건을 성별만으로 다르게 평가·강요하는지 살핀다.","[보도] 일부 청취자·누리꾼이 성별 이중잣대와 여성 비하라고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-098":{"elements":["[보도 인용·요약] 라마1004가 던파 이용자에게 ‘현생을 살라’는 취지로 말함. 전체 문구는 미확인.","게임 홍보 이벤트에서 준비 부족·게임 이해도 지적이 나온 뒤 이용자에게 반응.","던전앤파이터 이용자와 비판 시청자.","게임 홍보를 맡은 방송이며 참여 준비 문제도 동시에 제기됨. 후속 해명자의 말실수는 별도 발언.","[비판 해석] 이용자를 일상생활 없이 게임만 하는 집단으로 낙인찍었다.","[분석자 도출] 비판에 답하면서 취미 이용자의 생활·인격을 일괄 폄하하는지 확인한다.","[보도] 게이머 댓글에서 게임만 하는 폐인 프레임을 씌웠다고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-099":{"elements":["[보도 요약] 민지가 ‘칼국수가 뭐지’ 발언을 재해명하며 자신을 왜곡해서 본다는 취지로 응답.","팬 라이브에서 약 1년간 이어진 칼국수 관련 의문·비난을 설명.","자신의 과거 혼잣말과 반복 질문·비판자.","2023년 원발언과 2024년 해명 방송은 다른 시점. 음식 지식이 인격을 증명하지 않음.","[상반된 해석] 해명 말투가 공격적이라는 비판과 장기간 과도한 조롱에 대한 방어라는 해석.","[분석자 도출] 질문에 대한 말투를 문맥 속에서 검토하고, 사소한 지식 부족을 인격적 결함으로 확대하지 않는다.","[보도] 일부 누리꾼이 해명 태도·말투를 지적. 본인도 반복된 오해로 힘들었다고 설명."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-100":{"elements":["[보도 요약] 사유리가 이름을 밝히지 않은 대선배 가수에게 과거 성적 질문을 받았다고 경험을 말함.","유튜브에서 10여 년 전 촬영장 경험을 이야기한 뒤 시청자 추측이 확산.","진술 속 익명 가수. 추측으로 지목된 여러 가수는 실제 대상과 구분.","나이·방송사·직업 같은 단서만으로 가해자를 특정할 수 없음. 사유리는 언급된 인물들이 무관하다고 밝힘.","[수용 결과] 익명 피해 경험이 특정 인물에 대한 폭로로 오인돼 제3자 의혹이 퍼짐.","[분석자 도출] 피해 경험 진술과 시청자의 인물 특정 추측을 분리하고, 무관함을 밝힌 설명을 함께 반영한다.","[보도] 시청자 댓글·커뮤니티가 여러 인물을 추측. 특정 발언 자체를 비판한 주체는 별도 미확인."],"status":"문제 제기 보완","deletedAt":null,"history":[]},"OOPS-101":{"elements":["[보도 인용] 양상국: “유재석 씨”, “한 번만 더 이야기하면 혼냅니다.”","‘핑계고’에서 연인 배웅·연애관을 토론하다 유재석의 조언에 반응.","진행자 유재석의 발언과 조언.","예능적 친밀감·과장된 캐릭터라는 가능성이 있으나 실제 합의·사전 설정은 미확인.","[비판 해석] 농담의 범위를 넘어 상대를 위협·무시하는 태도로 보인다.","[분석자 도출] 친밀한 농담과 상대의 발언을 막는 공격적 태도를 순서·말투·반응으로 구분한다.","[보도] 일부 ‘핑계고’ 시청자가 무례함·시청 불편을 댓글로 지적."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-102":{"elements":["[보도 인용] 32기 영수: ① “연대 나온 애” ② 노령 반려견에 “마음의 준비를 하시겠네.”","① 다른 출연자 학력 이야기 ② 옥순의 반려견 나이를 들은 대화. 서로 다른 장면.","① 28기 옥순 ② 32기 옥순과 반려견. 같은 사람으로 합치지 않음.","기수·이름이 같은 출연자 식별이 필요. 반려견의 실제 건강 상태는 나이만으로 판단 불가.","[비판 해석] ① 사람을 학력으로 환원하고 낮춰 부름 ② 반려인의 상실을 배려 없이 단정.","[분석자 도출] 지위·학력으로 타인을 낮춰 지칭하거나 타인의 중요한 상실을 가볍게 예고하는지 각각 본다.","[보도] 출연자들이 말할수록 평가가 깎인다고 반응하고 시청자도 무례한 언행을 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-103":{"elements":["[보도 인용] 이관희: “연애도 못할 것 같은데 … 훈수.” 중간 생략.","‘솔로지옥’ 리액션 영상에서 홍진경이 만남 빈도에 의견을 내자 반응.","홍진경의 연애 경험·진행자 역할.","출연자와 패널은 역할이 다르며 개인 사생활로 패널 자격을 평가할 근거는 없음. 보도에 시즌 표기 불일치 존재.","[비판 해석] 의견 반박을 넘어 상대의 사생활·능력을 근거 없이 폄하했다.","[분석자 도출] 견해 차이를 상대의 경험·자격에 대한 인신공격으로 바꾸는지 확인한다.","[보도] 일부 시청자가 무례함을 비판했고 홍진경에게 보낸 사과가 공개됨."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-104":{"elements":["[보도 인용·요약] 박성광이 상대 선수의 플레이를 ‘뽀록’으로 낮추고 물러나라는 식으로 반응.","KIA 팬 대표로 출연한 KIA–삼성 경기 팬덤 중계.","상대 팀 삼성 선수들의 경기력·행동.","팬 관점의 편파 응원이 허용되는 형식이지만 공개 중계라는 조건. 일반 중립 해설과 다름.","[비판 해석] 응원을 넘어 상대 선수의 성과를 운으로 폄하하고 모욕했다.","[분석자 도출] 편파 응원의 형식과 상대 선수에 대한 인격적 공격·성과 폄하의 경계를 살핀다.","[보도] 일부 야구 팬이 원색적인 상대 선수 비난을 문제 삼음."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-105":{"elements":["[보도 요약] 김지민의 비공개 SNS 글에서 가족·유명인 등에 관한 모욕적 표현이 있었다는 주장이 유출됨.","소수 지인용 게시물이 외부로 유포된 뒤 논란. 영상 발언이 아님.","본인의 가족·연예인 등. 게시물별 대상·정확한 문구는 여기서 확정하지 않음.","무단 유출 및 일부 맥락 왜곡·허위 확산 주장 존재. 캡처 원본·작성 시점·진위 구분이 필요.","[보도된 해석] 사적 공간에서도 가족·타인을 심하게 비하했다는 비판. 당사자 측의 왜곡·권리침해 주장이 병존.","[분석자 도출] 사적 게시물의 진위·전체 문맥·공개 경위를 확인하고 유출된 단편을 사실로 단정하지 않는다.","[보도] 유출 이후 일부 이용자의 비판이 보도됨. 글별로 누가 무엇을 비판했는지는 보완 필요."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-106":{"elements":["[보도 인용] 이상훈: “좋아하는데 안 받아주니 … 폭력적 대응을 했다.” 중간 생략.","서울시의회 질의에서 신당역 스토킹 살인 사건의 원인을 설명.","가해자의 동기와 살해된 피해자의 대응.","사건은 스토킹·살인 피해이지 단순 연애 갈등이 아님. 피해자가 호감을 받아줘야 했다는 전제는 없음.","[비판 해석] 범죄를 거절당한 사랑의 문제로 축소하고 피해자에게 원인을 돌린다.","[분석자 도출] 가해행위를 애정의 표현으로 바꾸거나 피해자의 거절을 범죄 유발 책임으로 연결하는지 본다.","[보도] 피해자에 대한 2차 가해·부적절한 사건 설명이라는 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-107":{"elements":["[보도 인용·요약] 김재원이 5·18 정신의 헌법 수록에 “불가능하다”는 취지로 응답.","전광훈의 교회 예배에서 정치·지역 표를 거론한 질문에 답함.","5·18 정신의 헌법 수록과 정치적 공약.","5·18의 역사적 의미 및 당시 대통령·정당의 헌법 수록 공약이 배경. 원자료에는 다른 전광훈 관련 발언도 섞임.","[비판 해석] 역사적 기념·공약을 특정 집단의 표 계산 문제로 낮추고 약속을 부정했다.","[분석자 도출] 역사 인식 비판과 헌법 개정에 관한 정책 견해를 구분하고 공약·발언의 일치 여부를 본다.","[보도] 정치권·5·18 관련 비판이 공론화돼 본인이 발언을 사과하고 수록에 반대하지 않겠다고 밝힘."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-108":{"elements":["[보도 요약] 정태옥이 이혼하면 부천에 살고 경제적으로 망하면 인천에 산다는 식으로 도시를 설명.","TV에서 수도권 선거 판세·인천의 경제지표를 논하던 중.","부천·인천 주민과 이혼·경제적 곤란을 겪은 사람들.","도시별 지표 설명과 거주자의 삶을 실패의 단계로 배열하는 말은 다름.","[비판 해석] 지역 주민을 이혼·경제적 실패와 연결해 열등하게 낙인찍었다.","[분석자 도출] 거주 지역·가족 상태·경제 상황을 사람의 가치 서열로 표현하는지 본다.","[보도] 지역 주민·지역 정치인들이 지역 비하라고 항의하고 손해배상 등을 요구."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-109":{"elements":["[보도 인용] 유시민이 설난영을 향해 “제정신이 아니다”라고 평가.","정치 유튜브에서 김문수의 배우자가 남편을 지지하는 태도를 설명.","설난영의 판단·배우자 역할과 과거 노동 이력.","설난영은 김문수 후보의 배우자. 과거 직업을 연결한 표현의 전체 맥락과 실제 정책 발언을 구분해야 함.","[비판 해석] 여성·노동 경력을 낮춰 보고 정치인 배우자를 인격적으로 모욕했다. 본인은 여성·노동 비하 의도를 부인.","[분석자 도출] 정치적 견해 반박에 성별·직업·가족 관계를 인격적 열등함의 근거로 사용하는지 본다.","[보도] 국민의힘 등이 여성·노동 비하라고 비판했고 민주당 선대위도 발언 신중함을 언급."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-110":{"elements":["[보도 인용] 이하늬: “저는 깜시언니가 되었어요.”","야외 활동으로 그을린 자신의 피부를 SNS 사진 설명에 표현.","직접 지칭은 자신. 어휘가 어두운 피부·흑인을 연상시키는지가 쟁점.","‘깜시’가 피부색을 낮춰 부르는 표현으로 받아들여지는 용례. 해당 글에서 실제 흑인을 직접 지칭한 것은 아님.","[비판 해석] 자기 묘사여도 피부색 비하 표현을 일상화한다는 지적.","[분석자 도출] 직접 대상과 어휘의 집단적 비하 용례를 구분하고 해당 문맥의 의미를 확인한다.","[보도] 일부 팬이 흑인 비하로 비칠 수 있다고 지적."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-111":{"elements":["[보도 인용] 이휘재: “PD인가, 연기자인가 헷갈릴 정도로 의상을 ….” 일부 생략.","연기대상 생방송에서 패딩 차림의 성동일에게 반복 질문. 상대의 굳은 반응 뒤에도 이어짐.","성동일의 복장·배우로서의 외양.","시상식의 공개성·진행자 역할과 친분이 배경. 복장 이유·성동일의 실제 감정은 표정만으로 확정 불가.","[비판 해석] 복장 지적을 거듭해 상대를 공개적으로 무안하게 했다.","[분석자 도출] 농담 대상의 반응·반복 여부와 진행자의 공개적 권한을 함께 확인한다.","[보도] 일부 시청자가 무례한 진행·배려 부족이라고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-112":{"elements":["[보도 인용] 박지원이 김진표 등에게 “개XX들”이라고 말함.","‘겸손은 힘들다 뉴스공장’에서 법안 상정 문제를 이야기. 송출 전 사담이라고 생각한 발언으로 알려짐.","김진표·박병석·윤석열 등 정치인.","본인이 방송 시작을 인지했는지와 실제 송출 여부를 구분. 법안 처리 지연이 비판 배경.","[보도된 해석] 정치적 비판을 공적 방송에서 인신공격·욕설로 표출했다.","[분석자 도출] 정책·절차 비판과 대상 인격을 공격하는 욕설을 구분한다.","[보도] 공개 송출된 욕설이 논란이 됐고 당사자도 부적절한 언행이었다고 설명."],"status":"문제 제기 보완","deletedAt":null,"history":[]},"OOPS-113":{"elements":["[보도 인용] 31기 상철: “저걸 왜 앞에서 듣고 있냐.”","출연진이 최종회를 함께 보며 문밖에서 자신의 뒷담화를 듣는 순자 장면에 반응.","순자의 행동. 광수 등 다른 출연자의 개별 표현은 별도 확인 필요.","해당 회차의 뒷담화·소외 장면이 배경. 실제 집단 따돌림 의도까지는 확정되지 않음.","[비판 해석] 뒷담화를 한 쪽보다 들은 당사자를 탓해 소외를 정당화했다.","[분석자 도출] 문제 행동의 책임을 피해를 경험한 사람의 위치·대응으로 옮기는지 확인한다.","[보도] 일부 시청자가 피해자 탓·반성 없는 태도라고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-114":{"elements":["[당사자 진술을 보도가 인용] 지원자가 ‘촌 동네’, 여자친구 여부·차량 관련 농담을 들었다고 주장.","컴퓨터 매장 채용 면접 요청 전화. 유튜브에 해당 대화가 담긴 사례는 아님.","입사 지원자의 출신지·사생활·차량.","고용주–지원자 관계와 채용 목적이 배경. 녹취는 미확인이고 유튜버는 무례한 통화였음을 인정.","[비판 해석] 업무 무관 질문으로 지원자의 개인적 특성을 조롱하고 평가했다.","[분석자 도출] 채용 권한을 가진 사람이 직무와 무관한 사생활·출신지를 낮춰 평가하는지 본다.","[보도] 지원자가 채용에 필요한 질문인지 문제 제기. 일부 이용자도 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-115":{"elements":["[보도 인용] 양준일: “새 차를 중고차 가격에 사실 수 있는 기회.”","여성 스태프에게 남자친구가 없다는 말을 듣고 라이브 시청자에게 연락을 권함.","여성 스태프를 연애 대상으로 제시.","진행자–스태프 관계. 본인에게도 ‘중고’ 비유를 썼다는 해명이 있으나 상대를 상품화하는 효과와 별개.","[비판 해석] 여성을 구매 가능한 자동차에 비유해 가격·가치를 매겼다.","[분석자 도출] 사람을 거래 물건처럼 묘사하거나 연애 가능성을 상품 가격으로 평가하는지 살핀다.","[보도] 일부 시청자가 여성의 상품화·성적 대상화라고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-116":{"elements":["[보도 인용] 보아: “사귀지 않을 것 같다. 오빠가 아깝다.”","전현무와 취중 인스타그램 라이브 중 박나래와 사귀는지 묻는 시청자 질문에 답함.","현장에 없는 박나래와 전현무의 비교.","열애설은 확인된 교제 사실이 아님. 질문의 존재와 당사자들의 실제 관계를 구분.","[비판 해석] 부재중인 사람을 연애 상대로 낮춰 평가하고 소문을 재유통했다.","[분석자 도출] 제3자의 사생활을 다루며 사람의 가치를 우열로 비교하는지 확인한다.","[보도] 일부 시청자·누리꾼이 박나래 비하와 경솔한 언행을 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-117":{"elements":["[보도 인용] 이선민: “내 말 듣고 해야지 임마”, “장난하세요 그거 맞아요?”","계체 실패로 비판받은 나비예프의 경기 후 인터뷰에서 선수·통역사의 말을 끊음.","선수 나비예프와 통역사.","선수의 계체 초과·패널티라는 사실은 비판 질문의 배경. 선수의 잘못과 인터뷰어 태도는 별개.","[비판 해석] 사실 확인을 넘어 공개 질책·모욕을 했다. 강한 질문이 필요했다는 다른 반응도 존재.","[분석자 도출] 문제 행동을 추궁할 필요와 인터뷰 상대의 발언권·존중을 구분한다.","[보도] 일부 격투기 팬이 존중 없는 진행이라고 비판했고 반대 의견도 보도됨."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-118":{"elements":["[보도 요약] 진행자가 수빈에게 특정 신체 부위의 길이 측정을 요구하는 듯 말함. 수빈은 “수치스럽다”고 반응.","‘짠한형’ TXT 수빈·범규 출연 예고편에서 일부 장면이 공개.","게스트 수빈의 신체.","예고편은 전체 대화의 일부. 어떤 부위·정확한 요구·개별 발언자인지 기사만으로 확정되지 않음.","[비판 해석] 게스트를 성적으로 대상화하고 수치심을 웃음거리로 삼았다.","[분석자 도출] 신체 관련 요구의 구체적 의미·당사자 반응·편집 문맥을 확인한다.","[보도] 일부 TXT 팬이 성희롱성 연출이라고 반발하고 항의 행동을 예고."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-119":{"elements":["[보도 인용] 박동근: “리스테린 소독한 X, 독한 X.”","‘보니하니’ 관련 유튜브 생방송에서 미성년 출연자 채연에게 동료와 방송하는 소감을 묻다가 말장난.","미성년자 채연.","일부 이용자는 유흥업소 은어라고 해석. EBS는 가글을 소재로 한 장난이며 은어 의미를 몰랐다고 설명. 실제 통용 용례는 미확인.","[상반된 해석] 미성년자를 모욕·성적으로 비하했다는 비판과 단순한 라임 장난이라는 해명.","[분석자 도출] 모욕 표현 자체와 추가로 추정된 은어 의미를 구분해 각각 근거를 확인한다.","[보도] 일부 시청자·민원에서 미성년자에게 부적절한 언행이라고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-120":{"elements":["[보도 요약] 박위가 KTX 하차 중 낙상 사고와 당시 근무자의 대응에 대한 분노를 설명하며 CCTV를 공개.","휠체어 이용 안전 개선을 주장한 유튜브 영상에 사고 장면·대응 설명이 포함.","현장 근무자의 행동과 열차 이용 안전.","접근성·하차 지원의 안전 문제와 근무자 개인의 책임·신원 노출은 구분 필요. 사고 원인 확정은 별도 조사 대상.","[비판 해석] 도움을 준 개인을 공개 비난하고 사고 책임을 과도하게 돌렸다. 안전 개선 요구라는 본래 취지도 있음.","[분석자 도출] 공익적 안전 문제 제기와 개인 공개·책임 귀속의 근거를 각각 검토한다.","[보도] 일부 시청자가 CCTV 공개·근무자 비난 방식이 과도하다고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-121":{"elements":["[보도 인용] 양상국: “유튜브 가라 인마.”","‘놀라운 토요일’ 받아쓰기 게임의 힌트·상황극 과정에서 김해준 등과 의견 충돌.","김해준 등 동료 출연자의 제안·상황극.","예능의 과장된 캐릭터·게임 경쟁이라는 조건. 별도 ‘핑계고’ 발언과 같은 장면이 아님.","[비판 해석] 상대 제안을 무시하며 방송 자격을 낮춰 보거나 공격적 태도를 보였다.","[분석자 도출] 예능적 과장과 상대를 무시·위축시키는 말을 전후 반응 속에서 구분한다.","[보도] 일부 시청자·보도에서 무례한 언행·과도한 리액션이라고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-122":{"elements":["[보도 인용] 심규덕: “벽 보고 앉아 있어.” 원자료의 구체적 외모 비하 대사는 미확인.","‘연애전쟁’에서 동거 중인 이아영과 소비·생활비 문제로 갈등하는 장면.","연인 이아영의 행동·관계 내 위치.","경제적 지원 관계가 대화 배경이나 방송 속 설명이 실제 관계 전부를 증명하지 않음. 예고편·본편 구분 필요.","[비판 해석] 돈을 지원한다는 이유로 상대를 통제·낮춰 대했다는 해석. 이아영은 방송 밖의 모습은 다르며 옆에 있는 데는 이유가 있다고 설명.","[분석자 도출] 경제적 기여를 상대에 대한 모욕·통제의 근거로 삼는지 구체적 언어를 확인한다.","[보도] 프로그램 패널들이 폭언 장면을 강하게 비판. 별도 시청자 비판의 구체적 원문은 보완 필요."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-123":{"elements":["[보도 인용] 허구 인물의 대사: “완전 시골에서 온 사람들 같아 보이거든?”","강남구 외주 제작 메타버스 홍보 영상에서 캐릭터가 건물을 둘러보는 동료에게 말함.","건물을 보는 캐릭터와 ‘시골 출신’이라는 비교 대상.","지자체 공식 홍보 영상이며 등장인물은 제페토 웹드라마 캐릭터. 실제 방문객 인터뷰가 아님.","[비판 해석] 시골 사람을 촌스럽고 열등한 사람의 비유로 사용했다.","[분석자 도출] 출신 지역을 타인을 무안하게 하거나 낮추는 비교의 기준으로 쓰는지 본다.","[보도] 일부 이용자가 지역 비하·공식 홍보에 부적절한 설정이라고 비판."],"status":"보도 확인","deletedAt":null,"history":[]},"OOPS-124":{"elements":["[보도 요약] 김영희가 연예인에게 더 엄격한 잣대가 적용된다는 취지로 자기 경험·직업을 이야기.","라이브 화면에 학폭 관련 댓글이 올라온 때 자신의 이야기를 이어감. 댓글에 답한 것인지는 다툼.","본인 설명상 자신이 겪은 일·직업. 학폭 가해자를 직접 대상으로 삼았다는 근거는 미확인.","같은 화면·시간에 댓글이 있었던 사실만으로 질문–답변 관계가 성립하지 않음. 본인은 답한 적 없다고 밝힘.","[오인된 해석] 학폭 가해자를 옹호했다는 초기 해석. 정정·반박 자료가 있어 사실로 채택하지 않음.","[분석자 도출] 시간적 인접만으로 댓글과 발언을 응답 관계로 묶지 않고 실제 지시 대상을 확인한다.","[보도] 일부 초기 보도가 학폭 옹호로 문제 삼았고 김영희가 부인. 오해·정정 경위가 보도됨."],"status":"오인·반박","deletedAt":null,"history":[]}},"purged":{},"statusTypes":["보도 확인","기존 확정","검증 보류","문제 제기 보완","제공자료 정리","오인·반박","검토 중","검토 완료","제외 검토"]}'::jsonb) on conflict(id) do nothing;
